window.FIELD_META={"archives": [{"key": "form", "name": "形式灵感", "en": "Form", "color": "#7d8c4f", "row": 0}, {"key": "social", "name": "社会素材", "en": "Ground", "color": "#a5703f", "row": 1}, {"key": "lit", "name": "文学意向", "en": "Letters", "color": "#4f6d8c", "row": 2}, {"key": "art", "name": "经典艺术", "en": "Vision", "color": "#7d5f83", "row": 3}], "eras": ["先秦", "秦汉", "魏晋南北朝", "隋唐", "宋", "元明清", "近现代", "当代"], "halls": [{"id": "C1", "name": "字形之源", "sub": "文字里的田"}, {"id": "C2", "name": "格网之用", "sub": "纹样·界面·城市·棋戏"}, {"id": "C3", "name": "制度之田", "sub": "土地制度与地籍"}, {"id": "C4", "name": "水土之工", "sub": "水利与田型"}, {"id": "C5", "name": "农事之艺", "sub": "工序·图谱·知识"}, {"id": "C6", "name": "岁时之歌", "sub": "礼俗·节令·声音"}, {"id": "C7", "name": "笔端之心", "sub": "文学与抒情"}, {"id": "C8", "name": "凝视之史", "sub": "绘画·影像·大地艺术"}], "count": 208};
window.FIELD_DATA=[{"id": "form-2", "archive": "form", "title": "甲骨文\"田\"字", "author": "", "quote": "", "year": -1100, "era": "先秦", "eraIdx": 0, "eraText": "商代（约公元前 1300–前 1046）", "source": "殷墟甲骨刻辞（合集类著录）", "desc": "龟甲刻辞中的\"田\"字，象一块方整的耕地，内部以纵横线条分割成数块（多作四口、十字阡陌状）。", "tags": ["文字起源", "象形", "甲骨文", "网格雏形"], "note": "最早的\"田\"即网格本身——方框加十字界划，是汉字中极少数\"图形即意义\"的字例，可直接作为方块网格的标志原型。", "text": "", "img": "form_2.jpg", "hall": "C1", "hub": false, "x": 166.7, "y": 242.5, "rot": -1.17, "w": 142}, {"id": "form-3", "archive": "form", "title": "金文\"田\"字", "author": "", "quote": "", "year": -900, "era": "先秦", "eraIdx": 0, "eraText": "西周（约公元前 1046–前 771）", "source": "西周青铜器铭文（如令鼎、散氏盘等涉田土铭文）", "desc": "青铜器铭文中的\"田\"，字形外廓趋于方正饱满，内部界格简化为十字，介于图画与符号之间。", "tags": ["金文", "方块字", "田土制度"], "note": "散氏盘铭文详细记载了田界封域，\"田\"字在此既是文字也是土地产权图形，适合做\"边界/权属\"主题的视觉引用。", "text": "", "img": "form_3.jpg", "hall": "C1", "hub": false, "x": 496.7, "y": 250.2, "rot": 1.25, "w": 132}, {"id": "form-4", "archive": "form", "title": "《说文解字》释\"田\"", "author": "", "quote": "", "year": 121, "era": "秦汉", "eraIdx": 1, "eraText": "东汉（121 年成书）", "source": "许慎《说文解字·田部》", "desc": "原文：\"田，陈也。树谷曰田。象四口，十，阡陌之制也。\"", "tags": ["字书", "定义", "阡陌"], "note": "\"十\"为阡陌（南北曰阡，东西曰陌）——十字坐标划分空间的官方解释，是\"田=坐标系+方块\"的文字学依据。", "text": "", "img": "form_4.jpg", "hall": "C1", "hub": false, "x": 1108.7, "y": 485.7, "rot": -0.85, "w": 132}, {"id": "form-5", "archive": "form", "title": "井田制", "author": "", "quote": "", "year": -350, "era": "先秦", "eraIdx": 0, "eraText": "战国文献记西周制度（约公元前 4 世纪记述）", "source": "《孟子·滕文公上》（追述周制）", "desc": "\"方里而井，井九百亩，其中为公田。八家皆私百亩，同养公田。\"", "tags": ["井田", "九宫格", "理想国", "制度图形"], "note": "井字形九宫格——八私一公，是中国最古老也最理想化的空间分配图式，与九宫格、魔方阵同源，常用于城市规划与版面隐喻。", "text": "", "img": null, "hall": "C3", "hub": true, "x": 540.6, "y": 392.7, "rot": -1.57, "w": 162}, {"id": "form-6", "archive": "form", "title": "田字格与九宫格", "author": "", "quote": "", "year": 1200, "era": "宋", "eraIdx": 4, "eraText": "普及于宋元以后，沿用至今", "source": "蒙学书帖与习字格（传为王羲之《笔势论》所谓\"分间布白\"之法的后世实物化）", "desc": "红墨印刷的\"田\"字与\"米\"字辅助线方格，书法临习用。", "tags": ["书法", "习字格", "辅助线", "教育"], "note": "田字格=外框+横竖中线，是东亚人共同的空间分割认知图式；设计训练中可作\"网格启蒙\"的类比素材。", "text": "", "img": "form_6.jpg", "hall": "C1", "hub": true, "x": 4549.3, "y": 460.5, "rot": -2.36, "w": 142}, {"id": "form-7", "archive": "form", "title": "楷书\"田\"的间架", "author": "", "quote": "", "year": 650, "era": "隋唐", "eraIdx": 3, "eraText": "唐代（7 世纪）", "source": "唐楷碑刻拓本", "desc": "欧阳询《九成宫》一类楷书中\"田\"字：竖画内收，横折方正，中横居格心。", "tags": ["楷书", "间架结构", "黑体源头"], "note": "书法\"田\"字强调\"满而不胀\"，四边留白均匀——可直接转化为 logo 字标的中宫处理经验。", "text": "", "img": "form_7.jpg", "hall": "C1", "hub": false, "x": 3182.8, "y": 338.5, "rot": 1.85, "w": 132}, {"id": "form-8", "archive": "form", "title": "\"畾\"与三田叠字", "author": "", "quote": "", "year": 121, "era": "秦汉", "eraIdx": 1, "eraText": "东汉著录，字形更早", "source": "《说文解字》收录古文", "desc": "古文字中三\"田\"相叠为\"畾\"（léi），象田间块垒层层。", "tags": ["叠字", "古文字", "重复构成"], "note": "同一单元阵列重复即生新义，是\"模块化构成\"的文字先例，适合引用为重复网格的符号注脚。", "text": "", "img": null, "hall": "C1", "hub": false, "x": 1571.1, "y": 256.0, "rot": -0.4, "w": 152}, {"id": "form-9", "archive": "form", "title": "元阳哈尼梯田", "author": "", "quote": "", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "耕作历史逾 1300 年，唐代起有记载", "source": "云南红河元阳县哀牢山区；2013 年列入世界遗产（红河哈尼梯田文化景观）", "desc": "摄影：哀牢山坡面上数千级水田沿等高线盘旋，注水后如碎镜层叠，倒映天光。", "tags": ["梯田", "世界遗产", "等高线", "镜像"], "note": "顺应山形的最优曲线解——等高线即等高线的艺术，常用于表现\"秩序与自然妥协\"的视觉主题。", "text": "", "img": "form_9.jpg", "hall": "C4", "hub": true, "x": 3135.6, "y": 435.3, "rot": 1.74, "w": 142}, {"id": "form-10", "archive": "form", "title": "龙脊梯田", "author": "", "quote": "", "year": 1300, "era": "元明清", "eraIdx": 5, "eraText": "开垦始于元代，成形于明清", "source": "广西桂林龙胜各族自治县龙脊镇", "desc": "摄影：广西龙胜山区梯田，春灌期田面如链，曲线密集处形成强烈的等高线肌理。", "tags": ["梯田", "曲线肌理", "壮族瑶族"], "note": "与元阳相比田面更窄、曲线更密，适合做细密的等高线纹理背景。", "text": "", "img": "form_10.jpg", "hall": "C4", "hub": true, "x": 5134.4, "y": 261.0, "rot": -1.21, "w": 132}, {"id": "form-11", "archive": "form", "title": "青森稻田画（田んぼアート）", "author": "", "quote": "", "year": 1993, "era": "当代", "eraIdx": 7, "eraText": "1993 年–至今", "source": "日本青森县田舍馆村，1993 年起每年创作，后为各地效仿", "desc": "摄影：以紫、黄、绿等不同品种水稻在大田中\"种\"出的巨幅画面，观景台俯瞰方见全貌。", "tags": ["稻田画", "大地像素", "作物色彩", "社区艺术"], "note": "把农田当像素画布——\"种植即绘制\"，像素艺术的农业版，近年国内多地（沈阳锡伯族镇等）有同款实践。", "text": "", "img": "form_11.jpg", "hall": "C8", "hub": true, "x": 7144.4, "y": 485.4, "rot": 1.95, "w": 152}, {"id": "form-12", "archive": "form", "title": "越后妻有大地艺术祭", "author": "", "quote": "", "year": 2000, "era": "当代", "eraIdx": 7, "eraText": "2000 年首展，三年一届", "source": "日本新潟县十日町市·津南町，北川富朗策展", "desc": "图/装置：废弃梯田变身艺术现场——稻田上的平台、草间弥生《花开妻有》、废校改造等，艺术嵌入耕作景观。", "tags": ["大地艺术", "乡村复兴", "策展", "梯田装置"], "note": "\"以艺术复活乡村\"的范式案例，田的形式从生产空间转为展陈空间。", "text": "", "img": "form_12.jpg", "hall": "C8", "hub": true, "x": 7576.3, "y": 466.3, "rot": 0.2, "w": 132}, {"id": "form-13", "archive": "form", "title": "荷兰围田（Polder）几何地块", "author": "", "quote": "", "year": 1400, "era": "元明清", "eraIdx": 5, "eraText": "围田自中世纪，大规模围海为 20 世纪（须德海工程 1918 动工）", "source": "荷兰西部（北荷兰省、弗莱福兰省围海造田区）", "desc": "航拍：低于海平面的方整农田，直线水渠划分出严格的矩形网格，风车与沟渠交错。", "tags": ["围海造田", "直线网格", "水利工程", "航拍"], "note": "人类强加给泥滩的绝对网格——\"理性几何 vs 水面反光\"的经典航拍题材。", "text": "", "img": "form_13.jpg", "hall": "C4", "hub": false, "x": 5358.1, "y": 257.1, "rot": 1.19, "w": 142}, {"id": "form-14", "archive": "form", "title": "美国中西部圆形灌溉田", "author": "", "quote": "", "year": 1955, "era": "近现代", "eraIdx": 6, "eraText": "1950 年代起普及", "source": "北美大平原农业区", "desc": "卫星/高空摄影：内布拉斯加、堪萨斯等地大地上密布绿色正圆，如圆点阵列——中心支轴式喷灌机（center-pivot）轨迹。", "tags": ["卫星影像", "圆形", "喷灌", "大地波点"], "note": "效率逻辑意外造出的\"大地波点艺术\"，NASA Earth Observatory 长期收录，是几何图形自然涌现的极佳案例。", "text": "", "img": "form_14.jpg", "hall": "C4", "hub": false, "x": 6119.2, "y": 437.3, "rot": -0.48, "w": 132}, {"id": "form-15", "archive": "form", "title": "普罗旺斯薰衣草田", "author": "", "quote": "", "year": 1950, "era": "近现代", "eraIdx": 6, "eraText": "现代规模种植，20 世纪成形", "source": "法国东南部普罗旺斯（Valensole 高原）", "desc": "摄影：瓦朗索勒高原上条带状的紫田随缓坡起伏，色块排比如巨幅画布。", "tags": ["色块", "条带", "坡地", "紫色"], "note": "单色条带沿地形弯折——\"直线阵列+地形扰动\"的配色范本。", "text": "", "img": "form_15.jpg", "hall": "C4", "hub": false, "x": 6643.4, "y": 288.5, "rot": 0.2, "w": 162}, {"id": "form-16", "archive": "form", "title": "荷兰郁金香田", "author": "", "quote": "", "year": 1550, "era": "元明清", "eraIdx": 5, "eraText": "16 世纪郁金香种植以来，现代观光业 20 世纪成形", "source": "荷兰 Bollenstreek 球根花田区", "desc": "摄影：利瑟（Lisse）花田按品种分垄，红、黄、紫方块拼接成马赛克。", "tags": ["马赛克", "色块拼接", "花卉产业"], "note": "天然\"色卡田\"，可直接取样为马赛克配色方案。", "text": "", "img": "form_16.jpg", "hall": "C4", "hub": false, "x": 5188.6, "y": 470.5, "rot": -0.51, "w": 132}, {"id": "form-17", "archive": "form", "title": "元阳多依树日出 / 坝达夕照", "author": "", "quote": "", "year": 1995, "era": "当代", "eraIdx": 7, "eraText": "当代摄影经典题材（1990 年代后随世界遗产申报名声大噪）", "source": "元阳多依树、坝达等观景点", "desc": "摄影：梯田灌水季（11 月–次年 4 月）日出时田面反射朝霞，形成红金蓝交织的破碎镜面。", "tags": ["摄影", "光影", "镜面", "色彩"], "note": "同一网格因注水+光线获得完全不同的色彩状态，说明\"介质（水）改变形式感知\"。", "text": "", "img": "form_17.jpg", "hall": "C4", "hub": true, "x": 7362.6, "y": 466.2, "rot": 0.04, "w": 132}, {"id": "form-18", "archive": "form", "title": "麦田怪圈（Crop Circles）", "author": "", "quote": "", "year": 1980, "era": "当代", "eraIdx": 7, "eraText": "1970 年代末首现，1980–90 年代高峰期", "source": "英国威尔特郡等地；多为人工夜间压制作品，1991 年 Dave Chorley 与 Doug Bower 承认发起此风潮", "desc": "航拍：麦田倒伏形成的巨大几何图案——圆环、螺旋、分形阵列。", "tags": ["大地图形", "神秘主义", "航拍", "谷物"], "note": "从\"外星之谜\"到\"谷物画布\"——媒体如何为几何形式赋魅的完整案例史。", "text": "", "img": "form_18.jpg", "hall": "C8", "hub": true, "x": 7341.0, "y": 282.2, "rot": -2.27, "w": 162}, {"id": "form-19", "archive": "form", "title": "山形县麦田 / 日本田园\"里山\"景观", "author": "", "quote": "", "year": 2009, "era": "当代", "eraIdx": 7, "eraText": "传统景观，现作为可持续发展样板（联合国\"里山倡议\"2009）", "source": "日本\"里山\"（satoyama）典型景观，山形县庄内地方", "desc": "摄影/动画场景原型：盆地中块块水田与旱田拼贴，远处雪山（出羽三山）为背景。", "tags": ["里山", "拼贴景观", "人地共生"], "note": "田块大小、形状各不相同却和谐拼贴——\"不规则网格的秩序\"，对版式松弛感有启发。", "text": "", "img": "form_19.jpg", "hall": "C4", "hub": false, "x": 7499.9, "y": 637.8, "rot": 0.17, "w": 142}, {"id": "form-20", "archive": "form", "title": "范宽《溪山行旅图》中的田畴", "author": "", "quote": "", "year": 1020, "era": "宋", "eraIdx": 4, "eraText": "北宋（约 11 世纪初）", "source": "台北故宫博物院藏", "desc": "绢本巨嶂：大山脚下田畦、道路、商旅点景，田块以淡墨界出。", "tags": ["山水", "点景", "田畴"], "note": "田在山水画中承担\"比例尺\"功能——小田衬大山，形式对比的教材案例。", "text": "", "img": "form_20.jpg", "hall": "C8", "hub": false, "x": 4135.6, "y": 275.9, "rot": -0.81, "w": 152}, {"id": "form-21", "archive": "form", "title": "梵高《丰收》（Harvest at La Crau）", "author": "", "quote": "", "year": 1888, "era": "元明清", "eraIdx": 5, "eraText": "1888 年", "source": "梵高，阿姆斯特丹梵高博物馆藏", "desc": "油画：收割后的麦田与堆垛，前景农舍，远景阿尔卑斯山，色彩明快。", "tags": ["麦田", "色彩分块", "阿尔勒时期"], "note": "色块式的田面处理，可视为\"点彩之前的色块网格\"。", "text": "", "img": "form_21.jpg", "hall": "C8", "hub": true, "x": 5179.6, "y": 582.8, "rot": 0.43, "w": 152}, {"id": "form-22", "archive": "form", "title": "塞尚《圣维克多山》系列田景", "author": "", "quote": "", "year": 1890, "era": "元明清", "eraIdx": 5, "eraText": "1880s–1900s", "source": "保罗·塞尚，多馆收藏（大都会、费城美术馆等）", "desc": "油画：山坡田块以几何色块建构，房屋树木趋近立方体、圆柱体。", "tags": ["构成主义源头", "几何色块", "田园"], "note": "塞尚把田地和房屋\"几何化\"，直接通向立体主义——\"自然中的网格\"最权威的现代艺术论证。", "text": "", "img": "form_22.jpg", "hall": "C8", "hub": true, "x": 5311.3, "y": 639.8, "rot": 0.05, "w": 132}, {"id": "form-23", "archive": "form", "title": "葛饰北斋 / 歌川广重：浮世绘中的稻田", "author": "", "quote": "", "year": 1835, "era": "元明清", "eraIdx": 5, "eraText": "1830 年代", "source": "江户浮世绘", "desc": "木版画：雨中稻田、旅人穿行的田埂路（如广重《东海道五十三次》日本桥出发段、北斋富岳三十六景中的田景）。", "tags": ["浮世绘", "版画风", "雨景", "田埂"], "note": "浮世绘的平面分割+斜雨线条影响印象派；田埂斜线是极佳的引导线构图元素。", "text": "", "img": "form_23.jpg", "hall": "C8", "hub": false, "x": 5692.1, "y": 404.0, "rot": 1.27, "w": 152}, {"id": "form-24", "archive": "form", "title": "蒙德里安《红黄蓝构成》", "author": "", "quote": "", "year": 1929, "era": "近现代", "eraIdx": 6, "eraText": "1929–1930 年", "source": "皮特·蒙德里安，苏黎世美术馆等多版本", "desc": "油画：白底黑直线网格，嵌入红、黄、蓝色块。", "tags": ["风格派", "网格", "原色", "新造型主义"], "note": "尽管画的是城市与音乐节奏，但\"田\"字格+色块的纯形式与其同构——可作为\"田的形式=现代网格\"的桥接引用。", "text": "", "img": "form_24.jpg", "hall": "C2", "hub": true, "x": 6090.9, "y": 310.8, "rot": -2.29, "w": 132}, {"id": "form-25", "archive": "form", "title": "27 蒙德里安《百老汇爵士乐》", "author": "", "quote": "", "year": 1942, "era": "近现代", "eraIdx": 6, "eraText": "1942–1943 年", "source": "蒙德里安，纽约现代艺术博物馆（MoMA）藏", "desc": "油画：黄色直线网格中跳跃红蓝小块，如纽约街区的霓虹节奏。", "tags": ["网格", "城市节奏", "晚期"], "note": "从田字格到城市格——同一张网的两种内容，适合\"形式迁移\"主题。", "text": "", "img": "form_25.jpg", "hall": "C2", "hub": true, "x": 6458.7, "y": 326.0, "rot": -2.23, "w": 142}, {"id": "form-26", "archive": "form", "title": "Agnes Denes《麦田——一场对抗》", "author": "", "quote": "", "year": 1982, "era": "当代", "eraIdx": 7, "eraText": "1982 年（种植，1982 年 5 月收获）", "source": "美国艺术家 Agnes Denes 实施", "desc": "摄影/行为：纽约曼哈顿下城 Battery Park 垃圾填埋场上两英亩麦田，收获后麦秆绕世界巡展。", "tags": ["大地艺术", "城市农田", "观念艺术", "土地价值"], "note": "曼哈顿黄金地价上种麦子，田的形式成为对资本空间的质询——城市农业艺术的里程碑。", "text": "", "img": "form_26.jpg", "hall": "C8", "hub": false, "x": 7473.5, "y": 286.8, "rot": -1.29, "w": 132}, {"id": "form-27", "archive": "form", "title": "Richard Long 大地行走作品", "author": "", "quote": "", "year": 1970, "era": "近现代", "eraIdx": 6, "eraText": "1967 年起持续创作", "source": "英国艺术家 Richard Long", "desc": "摄影/记录：艺术家在草地上行走踩出的直线路径（A Line Made by Walking），或在田野中以石排成的圆（Cornwall 系列）。", "tags": ["大地艺术", "极简", "路径", "过程"], "note": "人在田地上的\"一笔\"——把田野当纸、脚步当笔，适合引用到\"足迹/轨迹\"设计主题。", "text": "", "img": "form_27.jpg", "hall": "C8", "hub": false, "x": 6713.7, "y": 395.4, "rot": 0.8, "w": 132}, {"id": "form-28", "archive": "form", "title": "四合院天井", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "形制成熟于元明清（13–20 世纪）", "source": "北京及华北传统民居形制", "desc": "图/建筑：四面房屋围合中央的露天方院，屋面坡向内院，四水归堂。", "tags": ["合院", "四水归堂", "内向空间"], "note": "建筑版的\"田\"——外实内空、向心排水；负空间即核心的空间观对中庭设计有启发。", "text": "", "img": "form_28.jpg", "hall": "C2", "hub": false, "x": 5535.5, "y": 267.0, "rot": 2.21, "w": 142}, {"id": "form-29", "archive": "form", "title": "设计与建筑", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "明清（14–19 世纪）", "source": "皖南徽派民居（歙县、黟县等地）", "desc": "摄影：高墙小天井，天光从头顶一方井口落下，四壁摩砖，盆景居中。", "tags": ["徽派", "天井", "光影", "马头墙"], "note": "天井被称为\"头顶的田\"——采光通风全靠这一口\"井\"，极致的垂直庭院。", "text": "徽州天井院", "img": "form_29.jpg", "hall": "C2", "hub": false, "x": 5757.2, "y": 324.3, "rot": 1.44, "w": 142}, {"id": "form-30", "archive": "form", "title": "田字格窗棂", "author": "", "quote": "", "year": 1100, "era": "宋", "eraIdx": 4, "eraText": "宋《营造法式》已有格眼制度，明清普及", "source": "中国传统建筑装修（小木作）", "desc": "图/木作：棂条以横竖等分构成\"田\"字单元的木窗，常见于江南园林与民居。", "tags": ["窗棂", "格子纹样", "木作", "借景"], "note": "田字棂心+窗后景物=天然的画中画网格，园林\"框景\"手法的基本单元。", "text": "", "img": "form_30.jpg", "hall": "C2", "hub": true, "x": 4099.5, "y": 419.3, "rot": 0.67, "w": 152}, {"id": "form-31", "archive": "form", "title": "市松纹（いちまつ）", "author": "", "quote": "", "year": 1750, "era": "元明清", "eraIdx": 5, "eraText": "江户时代（17–19 世纪）普及", "source": "日本传统纹样（因江户歌舞伎演员佐野川市松的袴纹样得名）", "desc": "图/纹样：两色方块交替排列的棋盘格，日本传统染织与建筑装饰常用。", "tags": ["棋盘格", "和纹样", "交替构成"], "note": "田字格的双色变体，东京奥运会 2020 会徽即市松纹现代演绎，是\"田→品牌图形\"的成功案例。", "text": "", "img": "form_31.jpg", "hall": "C2", "hub": false, "x": 5310.3, "y": 484.3, "rot": 1.96, "w": 152}, {"id": "form-32", "archive": "form", "title": "瑞士国际主义网格系统", "author": "", "quote": "", "year": 1961, "era": "近现代", "eraIdx": 6, "eraText": "1961 年瑞士首版，1981 年英文版", "source": "瑞士平面设计师 Josef Müller-Brockmann 著，Niggli 出版", "desc": "文/图：以数学网格统御字体、图片、留白的版面方法论，代表作《Grid Systems in Graphic Design》。", "tags": ["网格系统", "国际主义", "版式方法论"], "note": "把\"阡陌\"抽象为现代设计语法——所有田格思维的当代正统出处。", "text": "", "img": "form_32.jpg", "hall": "C2", "hub": false, "x": 6361.6, "y": 433.1, "rot": -0.4, "w": 162}, {"id": "form-33", "archive": "form", "title": "曼哈顿 1811 年网格规划", "author": "", "quote": "", "year": 1811, "era": "元明清", "eraIdx": 5, "eraText": "1811 年颁布", "source": "纽约州议会《Commissioners' Plan of 1811》", "desc": "规划图：纽约岛除少数斜街外，以 12 条南北大道 ×155 条东西街切出约 2000 个街区方块，一直铺满全岛。", "tags": ["城市规划", "街区网格", "北美"], "note": "人类史上最大胆的\"田字格城市\"——卖地逻辑造就的形式，至今定义纽约的城市体验。", "text": "", "img": "form_33.jpg", "hall": "C2", "hub": true, "x": 5505.5, "y": 439.9, "rot": 2.0, "w": 162}, {"id": "form-34", "archive": "form", "title": "中国象棋盘\"象走田\"", "author": "", "quote": "", "year": 1050, "era": "宋", "eraIdx": 4, "eraText": "北宋（11–12 世纪）定型，当代沿用", "source": "中国象棋（定型于北宋）", "desc": "图/规则：棋盘九宫与河界之外，棋规\"象（相）走田\"——棋子只能沿田字对角飞行，塞象眼则被阻。", "tags": ["棋类", "田字规则", "路径约束"], "note": "田字不只是形，还是运动规则——\"田=合法路径\"的规则设计，可迁移到交互与游戏设计。", "text": "", "img": "form_34.jpg", "hall": "C2", "hub": false, "x": 4576.9, "y": 313.0, "rot": 0.19, "w": 162}, {"id": "form-35", "archive": "form", "title": "跳房子 / 九宫格地画", "author": "", "quote": "", "year": 100, "era": "秦汉", "eraIdx": 1, "eraText": "古罗马已有石刻 hopscotch，各地世代流传", "source": "worldwide 民间游戏（中国叫\"跳房子\"\"造房子\"，英文 Hopscotch）", "desc": "图/游戏：粉笔或炭笔在地上画出连续方格（单格、双格、半圆），儿童单脚跳跃通关。", "tags": ["民间游戏", "地画", "身体路径"], "note": "田的形式从视觉变成\"用身体读写的界面\"——低成本、强互动，公共空间设计的民间智慧。", "text": "", "img": "form_35.jpg", "hall": "C2", "hub": false, "x": 1116.5, "y": 298.9, "rot": 1.61, "w": 132}, {"id": "form-36", "archive": "form", "title": "隈研吾 / 中国美术学院象山校区? — 改用：王澍 中国美术学院象山校区", "author": "", "quote": "", "year": 2006, "era": "当代", "eraIdx": 7, "eraText": "2004–2007 年分期建成", "source": "建筑师王澍（业余建筑工作室），杭州", "desc": "摄影/建筑：校园建筑沿山坡散落，保留农地肌理，屋顶起伏呼应田亩；材料回收自旧城拆迁。", "tags": ["当代建筑", "山水", "保留农田", "可持续"], "note": "把校园\"种\"回田里——建筑与田亩互相让位，获 2012 普利兹克奖的代表性语境。", "text": "", "img": "form_36.jpg", "hall": "C2", "hub": false, "x": 7195.4, "y": 623.2, "rot": -1.0, "w": 132}, {"id": "form-37", "archive": "form", "title": "《诗经·小雅·大田》", "author": "", "quote": "", "year": -800, "era": "先秦", "eraIdx": 0, "eraText": "西周至春秋（约公元前 11–前 6 世纪）", "source": "《诗经·小雅》", "desc": "诗文：\"大田多稼，既种既戒，既备乃事……\"", "tags": ["诗歌", "农耕", "赋"], "note": "田作为周人礼乐文明的物质基底，\"大田多稼\"四字即可作标题字/引文素材。", "text": "大田多稼，既种既戒，既备乃事。\n以我覃耜，俶载南亩。播厥百谷，既庭且硕，曾孙是若。\n既方既皁，既坚既好，不稂不莠。\n去其螟螣，及其蟊贼，无害我田稚。\n田祖有神，秉畀炎火。\n有渰萋萋，兴雨祈祈。雨我公田，遂及我私。\n彼有不获稚，此有不敛穧；\n彼有遗秉，此有滞穗：伊寡妇之利。\n曾孙来止，以其妇子，馌彼南亩，田畯至喜。\n来方禋祀，以其骍黑，与其黍稷。\n以享以祀，以介景福。", "img": null, "hall": "C7", "hub": false, "x": 160.9, "y": 393.2, "rot": -2.11, "w": 142}, {"id": "form-38", "archive": "form", "title": "陶渊明《归园田居》（其一）", "author": "", "quote": "", "year": 405, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋（约 405 年）", "source": "陶渊明《归园田居》组诗", "desc": "诗文：\"方宅十余亩，草屋八九间。榆柳荫后檐，桃李罗堂前。\"", "tags": ["田园诗", "隐逸", "中文经典"], "note": "定义了中文\"田园\"一词的情感内核——十亩方宅即最小的田格乌托邦。", "text": "方宅十余亩，草屋八九间。榆柳荫后檐，桃李罗堂前。", "img": null, "hall": "C7", "hub": true, "x": 2119.8, "y": 259.0, "rot": -0.27, "w": 162}, {"id": "form-39", "archive": "form", "title": "海子《麦地》", "author": "", "quote": "", "year": 1985, "era": "当代", "eraIdx": 7, "eraText": "1980 年代中（1985 年前后）", "source": "海子（査海生）短诗", "desc": "诗文：\"麦地／别人看见你／觉得你温暖，美丽／我则站在你痛苦质问的中心……\"", "tags": ["当代诗", "麦地", "抒情"], "note": "第三代诗歌地标意象，\"麦地\"成为乡土中国的精神缩写，文案引用气质苍凉的来源。", "text": "吃麦子长大的\n在月亮下端着大碗\n碗内的月亮\n和麦子\n一直没有声响\n和你俩不一样\n在歌颂麦地时\n我要歌颂月亮\n月亮下\n连夜种麦的父亲\n身上像流动金子\n月亮下\n有十二只鸟\n飞过麦田\n有的衔起一颗麦粒\n有的则迎风起舞，矢口否认\n看麦子时我睡在地里\n月亮照我如照一口井\n家乡的风\n家乡的云\n收聚翅膀\n睡在我的双肩\n麦浪——\n天堂的桌子\n摆在田野上\n一块麦地\n收割季节\n麦浪和月光\n洗着快镰刀\n月亮知道我\n有时比泥土还要累\n而羞涩的情人\n眼前晃动着\n麦秸\n我们是麦地的心上人\n收麦这天我和仇人\n握手言和\n我们一起干完活\n合上眼睛，命中注定的一切\n此刻我们心满意足地接受\n妻子们兴奋地\n不停用白围裙\n擦手\n这时正当月光普照大地。\n我们各自领着\n尼罗河，巴比伦或黄河\n的孩子 在河流两岸\n在群蜂飞舞的岛屿或平原\n洗了手\n准备吃饭\n就让我这样把你们包括进来吧\n让我这样说\n月亮并不忧伤\n月亮下\n一共有两个人\n穷人和富人\n纽约和耶路撒冷\n还有我\n我们三个人\n一同梦到了城市外面的麦地\n麦浪滚滚\n在这美丽的月亮下\n人们在奔跑\n啊，麦地\n我爱你\n空空的麦地", "img": null, "hall": "C7", "hub": true, "x": 7639.6, "y": 251.5, "rot": 2.0, "w": 152}, {"id": "form-40", "archive": "form", "title": "中国《耕种》题材纪录片《乡村里的中国》", "author": "", "quote": "", "year": 2013, "era": "当代", "eraIdx": 7, "eraText": "2013 年", "source": "导演焦波，中央新影", "desc": "纪录片：鲁中山区杓峪村农民杜深忠一家种 peach? ——片中真实地记录果园与田地劳作、村民与土地的纠葛。", "tags": ["纪录片", "乡土", "真实叙事"], "note": "去除滤镜的当代中国田与人——与唯美田园形成对照，报告类内容的质感参考。", "text": "", "img": "form_40.jpg", "hall": "C8", "hub": false, "x": 7573.4, "y": 587.5, "rot": 0.26, "w": 152}, {"id": "form-41", "archive": "form", "title": "周杰伦《稻香》MV", "author": "", "quote": "", "year": 2008, "era": "当代", "eraIdx": 7, "eraText": "2008 年", "source": "周杰伦专辑《魔杰座》，MV 取景台湾乡村", "desc": "MV 影像：台湾乡间稻田、萤火虫、纸飞机、水牛——\"还记得你说家是唯一的城堡，随着稻香河流继续奔跑\"。", "tags": ["流行音乐", "MV", "稻田", "怀旧"], "note": "华语流行文化中最广传播的\"田=治愈与回家\"符号，情绪营销可借用的集体记忆。", "text": "", "img": "form_41.jpg", "hall": "C8", "hub": false, "x": 7274.9, "y": 596.7, "rot": -2.19, "w": 162}, {"id": "form-42", "archive": "form", "title": "\"城市农田\"与社区农园（Community Gardens）", "author": "", "quote": "", "year": 1980, "era": "当代", "eraIdx": 7, "eraText": "1970 年代起兴盛，21 世纪普及", "source": "全球都市农业运动（一米菜园法由 Mel Bartholomew 1981 年著作推广）", "desc": "图/实践：纽约、伦敦、上海等城市隙地中的方格认养菜园——一米菜园（Square Foot Gardening）网格箱、高架花床。", "tags": ["都市农业", "一米菜园", "社区营造", "可持续"], "note": "田缩到一平方米仍保持田的完整形式——\"微缩田\"证明田的核心是划分而非尺度，可做桌面盆栽/微景观产品概念。", "text": "", "img": "form_42.jpg", "hall": "C8", "hub": false, "x": 7180.7, "y": 326.1, "rot": -1.81, "w": 142}, {"id": "form-43", "archive": "form", "title": "卡巴科夫夫妇《梯田》（《稻田》）", "author": "", "quote": "", "year": 2000, "era": "当代", "eraIdx": 7, "eraText": "2000 年（此后常设）", "source": "俄罗斯艺术家伊利亚·卡巴科夫与艾米利亚·卡巴科夫，日本新潟越后妻有大地艺术祭首展（松代地区）", "desc": "装置：在一片梯田之间竖立多组彩色剪影式人物雕塑，呈现\"犁田、播种、插秧、割稻、进城贩卖\"的完整农耕过程，其间竖立歌颂农作的日文诗文本牌。", "tags": ["大地艺术", "农耕叙事", "剪影装置", "越后妻有"], "note": "最经典的\"田上叙事装置\"——作品展出后，梯田主人重拾耕作，当地还成立了\"松代梯田银行\"，是艺术激活农耕的标志性案例。", "text": "", "img": "form_43.jpg", "hall": "C8", "hub": false, "x": 7506.5, "y": 419.8, "rot": 0.72, "w": 142}, {"id": "form-44", "archive": "form", "title": "Alan Sonfist《时间景观》（Time Landscape）", "author": "", "quote": "", "year": 1978, "era": "近现代", "eraIdx": 6, "eraText": "1978 年建造，至今仍在生长演替", "source": "美国艺术家 Alan Sonfist，纽约 Laguardia Place 与 Houston St 街角", "desc": "装置/长期地景：在纽约曼哈顿格林尼治村一块三角地上，用考古与植物学证据复原 17 世纪欧洲人到来前的原生植被景观——橡树、山胡桃、蕨类与草本地被。", "tags": ["复原景观", "生态艺术", "城市中的田", "时间"], "note": "一块\"活着的田\"——把城市街区还原成前殖民时代的植物群落，40 多年持续演替，是\"时间维度装置\"的鼻祖。", "text": "", "img": "form_44.jpg", "hall": "C8", "hub": false, "x": 6097.3, "y": 612.8, "rot": 1.56, "w": 132}, {"id": "form-45", "archive": "form", "title": "Mel Chin & Rufus Chaney《复活之田》（Revival Field）", "author": "", "quote": "", "year": 1991, "era": "当代", "eraIdx": 7, "eraText": "1991 年起，持续数年", "source": "艺术家 Mel Chin 与植物学家 Rufus Chaney 合作，圣保罗", "desc": "装置/科学艺术：在受重金属污染的明尼苏达 Pig's Eye 垃圾填埋场划出一圈试验田，种植超积累植物（如遏蓝菜）吸收土壤中的镉、锌等重金属，田块外立环形标牌。", "tags": ["修复艺术", "科学合作", "污染地块", "实验田"], "note": "田作为\"活的净化器\"——植物修复（phytoremediation）概念首次进入当代艺术语境，证明农田形式可以承担环境功能。", "text": "", "img": "form_45.jpg", "hall": "C8", "hub": false, "x": 7806.2, "y": 274.0, "rot": -1.07, "w": 142}, {"id": "form-46", "archive": "form", "title": "草间弥生《花开妻有》（妻有に咲く花）", "author": "", "quote": "", "year": 2003, "era": "当代", "eraIdx": 7, "eraText": "2003 年（常设）", "source": "草间弥生，越后妻有大地艺术祭，新潟十日町农舞台（Hachikura/农舞台区域）", "desc": "装置：数座高达数米的巨型波点花卉雕塑（郁金香、百合、菊花），以鲜烈色彩绽放在越后妻有的田野与农舞台之间。", "tags": ["波点", "巨构花卉", "田野点缀", "越后妻有"], "note": "把草间的\"花\"放进真实的田里——无限增殖的圆点花朵与单调水田形成强烈图底对比，是\"异质物入田\"式装置的代表。", "text": "", "img": "form_46.jpg", "hall": "C8", "hub": false, "x": 7785.9, "y": 438.9, "rot": -2.02, "w": 152}, {"id": "form-47", "archive": "form", "title": "昆山尚明甸村\"中国航天\"稻田艺术", "author": "", "quote": "", "year": 2023, "era": "当代", "eraIdx": 7, "eraText": "2023 年 7 月进入观赏期（2019 年前后起持续）", "source": "江苏苏州昆山市张浦镇尚明甸村", "desc": "大地装置：约 200 亩水田里以紫、黄、绿等彩色稻种出\"仰望星空\"\"中国航天\"等主题图案，含创意字符与航天器图形，为该村连续第四年创作。", "tags": ["稻田画", "航天主题", "苏南乡村", "农文旅"], "note": "中国东部稻田画规模化代表，流程含育种、图案设计、精准测绘、插秧、田间管理五步，配套昆曲主题文创，展示\"精确测绘+农业\"的技术化路径。", "text": "", "img": "form_47.jpg", "hall": "C2", "hub": false, "x": 7175.6, "y": 729.9, "rot": 0.89, "w": 152}, {"id": "form-48", "archive": "form", "title": "济南长家庄稻田艺术项目", "author": "", "quote": "", "year": 2022, "era": "当代", "eraIdx": 7, "eraText": "2022 年首作，每年更新", "source": "山东济南荷花路街道长家庄，黄河生态现代农业示范区/城乡融合发展试验区（街道与山东土地发展集团共建）", "desc": "大地装置：约 40 亩稻田为画布，每年变换主题——2023 年\"丰收\"\"我爱济南\"等四幅，2024 年\"庆祝新中国成立 75 周年\"，2025 年\"春满济南\"\"荷花足球\"，均为紫黄绿多色稻绘制的巨型图幅。", "tags": ["稻田画", "城乡融合", "年度策展", "黄河主题"], "note": "主题是每年经头脑风暴结合社会热点与本地特色确定的——稻田在此成为\"年度公共议题画布\"，是大地装置的\"连载化\"运营案例。", "text": "", "img": "form_48.jpg", "hall": "C2", "hub": false, "x": 7777.3, "y": 600.7, "rot": 2.41, "w": 142}, {"id": "form-49", "archive": "form", "title": "泰顺卢梨大地艺术展（\"风之褶\"\"∞环·麦阶剧场\"等）", "author": "", "quote": "", "year": 2025, "era": "当代", "eraIdx": 7, "eraText": "2025 年 5 月 4 日启幕", "source": "浙江温州泰顺县三魁镇卢梨村，策展团队历时半年选址策划", "desc": "装置群：春耕时节的黄绿梯田间散布 6 件装置与 2 个画展区——\"风之褶\"以布幔连接的巨型构筑、\"∞环·麦阶剧场\"环形麦秆阶梯座席、\"山谷回响\"钢筋曲线、\"辉晶山脉\"镜面折射天地。", "tags": ["梯田装置", "镜面", "布幔", "乡村重建"], "note": "以\"没有天花板的艺术馆\"为概念——装置沿梯田等高线落位，材料呼应梯田层级，是近年国内\"田+轻构筑\"组合的最新样本。", "text": "", "img": "form_49.jpg", "hall": "C8", "hub": false, "x": 7409.7, "y": 692.1, "rot": 0.28, "w": 142}, {"id": "form-50", "archive": "form", "title": "海南儋州大地艺术节 · 山兰梯田装置群", "author": "", "quote": "", "year": 2023, "era": "当代", "eraIdx": 7, "eraText": "2023 年 9 月 29 日开幕", "source": "海南儋州云舍松涛·海南中国村，首届海南儋州大地艺术节", "desc": "装置群：首期五大装置镶嵌于山兰梯田与瀑布景观中，采用海南在地材料创作——竹编簸箕、竹编斗笠、陶土、木块等，配\"云隐野间\"艺术展与自然课堂体验。", "tags": ["大地艺术节", "在地材料", "黎族山兰稻", "竹编"], "note": "以山兰稻（海南黎族传统旱稻）梯田为场域、以农具竹编为材料——\"材料即田的历史\"，是少数民族稻作文化与装置艺术结合的在地化样本。", "text": "", "img": "form_50.jpg", "hall": "C8", "hub": false, "x": 7298.6, "y": 741.8, "rot": -1.97, "w": 142}, {"id": "social-1", "archive": "social", "title": "井田制", "author": "", "quote": "", "year": -700, "era": "先秦", "eraIdx": 0, "eraText": "周代", "source": "《孟子·滕文公上》《周礼·地官·小司徒》《汉书·食货志》", "desc": "《孟子·滕文公上》：“方里而井，井九百亩，其中为公田，八家皆私百亩，同养公田。”一方里之田按“井”字划为九区，公田居中、私田环列。", "tags": ["井田", "九宫格", "方里而井", "公田私田"], "note": "“井”字道路把一里之地划为九块方田，公田居中、私田环列；“九夫为井，四井为邑”进一步把人户编入格网。井田是“田”字十字分格形态的制度源头，田字格、里坊、棋盘街等均由此衍出。", "text": "", "img": "social_1.jpg", "hall": "C3", "hub": true, "x": 786.2, "y": 884.9, "rot": -1.74, "w": 162}, {"id": "social-2", "archive": "social", "title": "沟洫制度", "author": "", "quote": "", "year": -500, "era": "先秦", "eraIdx": 0, "eraText": "先秦", "source": "《周礼·地官·遂人》《考工记·匠人》", "desc": "《周礼·地官·遂人》：“夫间有遂，遂上有径；十夫有沟，沟上有畛；百夫有洫，洫上有涂；千夫有浍，浍上有道；万夫有川，川上有路。”遂、沟、洫、浍、川五级水道与径、畛、涂、道、路五级道路逐级配套。", "tags": ["沟洫", "五级水道", "配套道路", "井田水网"], "note": "沟洫与道路逐级配套，把“井”字的十字划格放大为覆盖整个农耕区的分级纵横系统——遂沟洫浍是“田”字十字笔画的系统性扩展，水道与道路在格网中各占一线。", "text": "", "img": "social_2.jpg", "hall": "C4", "hub": false, "x": 693.6, "y": 979.7, "rot": 2.44, "w": 132}, {"id": "social-3", "archive": "social", "title": "均田制", "author": "", "quote": "", "year": 485, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "北魏—唐", "source": "《魏书·食货志》《通典·食货》；敦煌吐鲁番户籍文书", "desc": "北魏孝文帝太和九年（485）颁均田令，按人口授露田、桑田、麻田；隋唐承袭，至建中元年（780）两税法施行而废。", "tags": ["均田", "露田桑田", "编户齐民", "田亩四至"], "note": "按人口授田，户籍与田亩一一对应；敦煌吐鲁番文书中“田亩四至”（东至某田、西至某陌）以方位词记录田块边界。均质授田形成棋盘式田制肌理，格网形态由此成为农业地理的通行底图。", "text": "", "img": "social_3.jpg", "hall": "C3", "hub": false, "x": 2203.0, "y": 857.0, "rot": 0.41, "w": 132}, {"id": "social-4", "archive": "social", "title": "屯田制", "author": "", "quote": "", "year": -110, "era": "秦汉", "eraIdx": 1, "eraText": "汉—唐", "source": "《汉书·西域传》《三国志·魏书》；居延汉简、敦煌汉简", "desc": "汉武帝置张掖、酒泉等郡徙民屯田，曹魏许下屯田“得谷百万斛”；军屯以营—屯—地块三级组织垦殖边地，田块按军事编制方格布局。", "tags": ["军屯", "营屯地块", "居延汉简", "边地垦殖"], "note": "田块按军事编制呈方格布局，与营垒、烽燧、渠道在边地上叠加成片。居延汉简“田卒簿”逐日记录垦殖——格网田制与边防工事共用一套方格排布逻辑。", "text": "", "img": "social_4.jpg", "hall": "C3", "hub": false, "x": 1585.5, "y": 987.0, "rot": -1.78, "w": 152}, {"id": "social-5", "archive": "social", "title": "籍田礼", "author": "", "quote": "", "year": -1000, "era": "先秦", "eraIdx": 0, "eraText": "周—清", "source": "《诗经·周颂》《礼记·月令》《明会典》；北京先农坛", "desc": "《诗经·周颂·载芟》“春藉田而祈社稷也”。天子孟春亲执耒耜“三推一拨”；明清于北京先农坛行礼，皇帝在“一亩三分地”亲耕，观耕台上阅三公九卿终亩。", "tags": ["籍田", "亲耕", "先农坛", "一亩三分地"], "note": "“一亩三分地”以最小田块承载国家重农仪式：皇帝台上、亲王台下、耤田在坛前，垂直高差区分礼制等级。田块在此是礼制空间的坐标原点，观耕建筑围绕它布置。", "text": "", "img": "social_5.jpg", "hall": "C6", "hub": false, "x": 558.3, "y": 854.1, "rot": -2.52, "w": 132}, {"id": "social-6", "archive": "social", "title": "田猎", "author": "", "quote": "", "year": -1100, "era": "先秦", "eraIdx": 0, "eraText": "先秦", "source": "《周礼·春官》《左传》；甲骨文字形", "desc": "甲骨文“田”兼表农田与畋猎；《周礼》载春蒐、夏苗、秋狝、冬狩四时田猎之礼，以车徒列阵合围禽兽于划定地界之内，获兽以祭、以膳、以皮革充军用。", "tags": ["田猎", "四时之畋", "字源", "围猎方阵"], "note": "“田”字甲骨文本义兼指农田与围猎之场——狩猎的合围阵形与农田的方格划分共用同一字形，先于文献而存在。这是“田=方块+边界”最直接的字源证据，田字形态早于井田制记载数百年。", "text": "", "img": "social_6.jpg", "hall": "C6", "hub": false, "x": 112.0, "y": 846.3, "rot": 1.95, "w": 132}, {"id": "social-7", "archive": "social", "title": "三权分置", "author": "", "quote": "", "year": 2016, "era": "当代", "eraIdx": 7, "eraText": "当代", "source": "2014年中央一号文件；《关于完善农村土地所有权承包权经营权分置办法的意见》（2016）", "desc": "2014年中央一号文件提出农村土地所有权、承包权、经营权“三权分置”，2016年中办、国办印发专门意见；农地经营权可流转、入股、抵押，承包权与经营权正式分离。", "tags": ["三权分置", "权利分层", "田块登记"], "note": "同一块田分为所有权、承包权、经营权三层，各层分别登记、可分别流转——田的空间边界不变，权利在地块上分层叠置。田的单元成为多套系统共用的登记基准。", "text": "", "img": "social_7.jpg", "hall": "C3", "hub": false, "x": 7150.6, "y": 975.1, "rot": 2.12, "w": 132}, {"id": "social-8", "archive": "social", "title": "鱼鳞图册", "author": "", "quote": "", "year": 1368, "era": "元明清", "eraIdx": 5, "eraText": "明清", "source": "《明史·食货志》；洪武《鱼鳞图册》；徽州鱼鳞图册遗存", "desc": "明清两代为征田赋编制的地籍图册：以县为单位将每块田按形状绘制编号，载四至、业主、税则，册内田块图形鳞次栉比状如鱼鳞。洪武元年（1368）即派国子生赴各州县核田丈地。", "tags": ["鱼鳞图册", "地籍", "田块图形", "四至编号"], "note": "每块田的形状、边界、业主、税则被绘成编号图形装订成册——田的形态第一次成为官府文档的记录对象。以图形登记田产的图册制度，是格网式土地信息的图像档案，与黄册（户册）并行构成赋役两大册籍。", "text": "", "img": "social_8.jpg", "hall": "C3", "hub": false, "x": 5363.4, "y": 894.5, "rot": 0.99, "w": 142}, {"id": "social-9", "archive": "social", "title": "哈尼梯田", "author": "", "quote": "", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "云南红河", "source": "红河哈尼梯田文化景观（UNESCO世界遗产，2013）；《哈尼族四季生产调》（国家级非遗）", "desc": "云南红河元阳等县哀牢山间的哈尼梯田，依“森林—村寨—梯田—水系”四素同构垂直布局，最大落差逾千米；2013年以文化景观列入《世界遗产名录》。", "tags": ["梯田", "四素同构", "世界遗产", "等高线"], "note": "田块沿等高线依山开筑，森林涵水于顶、村寨居中、梯田承水而下。方格单元在山地条件下沿等高线弯曲排布——保留格网划分逻辑的曲线化变体，田埂即等高线的实物化。", "text": "", "img": "social_9.jpg", "hall": "C4", "hub": true, "x": 3528.7, "y": 883.4, "rot": -1.02, "w": 142}, {"id": "social-10", "archive": "social", "title": "龙脊梯田", "author": "", "quote": "", "year": 1300, "era": "元明清", "eraIdx": 5, "eraText": "广西龙胜", "source": "广西龙胜各族自治县龙脊镇；全球重要农业文化遗产候选地", "desc": "广西龙胜龙脊山，壮族、瑶族自元代起垦殖，梯田盘山自河谷直至海拔千米之上；平安寨壮梯田与金坑瑶梯田为其双璧。", "tags": ["梯田", "壮族瑶族", "等高线", "高差垦殖"], "note": "“山有多高、田有多高”——田块弧度由水的自流走向决定，每块田即一段等高线。方块田的直角边在坡地上全部转为弧线，格网逻辑与地形条件结合的典型样本。", "text": "", "img": "social_10.jpg", "hall": "C4", "hub": true, "x": 5308.9, "y": 855.2, "rot": -0.38, "w": 132}, {"id": "social-11", "archive": "social", "title": "紫鹊界梯田", "author": "", "quote": "", "year": 1200, "era": "宋", "eraIdx": 4, "eraText": "湖南新化", "source": "湖南新化紫鹊界梯田（世界灌溉工程遗产，2014）", "desc": "湖南新化水车镇紫鹊界梯田八万余亩，无山塘、无水库，灌溉全凭森林土壤涵养水源、经田埂缺口自流下渗；2014年列入首批世界灌溉工程遗产。", "tags": ["梯田", "自流灌溉", "世界灌溉工程遗产"], "note": "每块田既是下游田的过水通道，也是蓄水单元，田块按高差串联成隐性水网。格网的每个单元兼具输水与蓄水双重功能，是田块之间相互依存的连网结构。", "text": "", "img": "social_11.jpg", "hall": "C4", "hub": false, "x": 4149.3, "y": 1124.4, "rot": 0.81, "w": 132}, {"id": "social-12", "archive": "social", "title": "加榜梯田", "author": "", "quote": "", "year": 1200, "era": "宋", "eraIdx": 4, "eraText": "贵州从江", "source": "贵州从江县加榜乡；从江侗乡稻鱼鸭系统（全球重要农业文化遗产）", "desc": "贵州从江县加榜乡月亮山腹地，苗族依山而耕，田块随山势盘旋于云雾之间；“稻—鱼—鸭”共生，禾晾（晾谷架）与吊脚楼点缀田畔。", "tags": ["梯田", "苗族", "稻鱼鸭共生", "禾晾"], "note": "受地形所限，田块面积小、形状随山势各不相同，边缘犬牙交错。小尺度碎田展示了格网单元在不规则地形中的适应性拼合；成排禾晾是田畔的垂直晾晒构件，构成田块之外的第二套木架矩阵。", "text": "", "img": "social_12.jpg", "hall": "C4", "hub": false, "x": 4621.2, "y": 895.2, "rot": -1.38, "w": 152}, {"id": "social-13", "archive": "social", "title": "桑基鱼塘", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "珠三角 / 湖州", "source": "浙江湖州桑基鱼塘系统（GIAHS，2017）；岭南方志", "desc": "低洼地挖泥成塘、堆泥为基：塘基种桑、桑叶饲蚕、蚕沙喂鱼、塘泥壅桑；浙江湖州桑基鱼塘系统2017年列入全球重要农业文化遗产。", "tags": ["基塘", "水陆交替", "物质循环", "GIAHS"], "note": "基与塘方格交替排布，水（塘）与地（基）在同一格网上轮转。格网形态在两种介质间保持划分逻辑不变——方格单元既是生产单元也是循环路径的一环。", "text": "", "img": "social_13.jpg", "hall": "C4", "hub": false, "x": 5573.9, "y": 991.2, "rot": 0.88, "w": 142}, {"id": "social-14", "archive": "social", "title": "稻田养鱼", "author": "", "quote": "", "year": 1200, "era": "宋", "eraIdx": 4, "eraText": "浙江青田", "source": "浙江青田稻鱼共生系统（GIAHS，2005）", "desc": "浙江青田县稻鱼共生系统，田中放养红色品系“田鱼”，鱼食虫草、粪可肥田，稻鱼双收；2005年成为中国首个全球重要农业文化遗产（GIAHS）。", "tags": ["稻鱼共生", "GIAHS", "田鱼", "一田两收"], "note": "一块田同时产出稻与鱼——田的方格单元在物理边界之外增加了生态层面的复合内容。“一田两收”是格子功能复合化的农业实例，红色田鱼为千年选育的固定品系。", "text": "", "img": "social_14.jpg", "hall": "C4", "hub": false, "x": 4659.7, "y": 1013.0, "rot": -1.59, "w": 162}, {"id": "social-15", "archive": "social", "title": "圩田", "author": "", "quote": "", "year": 1000, "era": "宋", "eraIdx": 4, "eraText": "太湖流域", "source": "《宋史·河渠志》；太湖塘浦圩田遗址", "desc": "筑堤围水、堤内成田：太湖流域塘浦圩田“五里一纵浦、七里一横塘”，堤—渠—田—闸四位一体；范仲淹《答手诏条陈十事》专论江南圩田水利。", "tags": ["圩田", "塘浦", "堤渠田闸", "经纬水网"], "note": "塘纵浦横织成框架，圩田居于框架之内；堤是格网外框，水闸是可启闭的边界。田块由水利边界的纵横叠加而成——五里七里的固定间距使整个平原成为按尺寸打格的田字大地。", "text": "", "img": "social_15.jpg", "hall": "C4", "hub": false, "x": 4143.0, "y": 867.6, "rot": 0.06, "w": 142}, {"id": "social-16", "archive": "social", "title": "架田", "author": "", "quote": "", "year": 1300, "era": "元明清", "eraIdx": 5, "eraText": "宋元", "source": "王祯《农书》（1313）；《辞海》“葑田”条", "desc": "元王祯《农书》：“架田，以木缚架为田丘，浮系水面，以葑泥附木架上而种艺之，其木架随水升降。”又名葑田，随水涨落、可移动拼合。", "tags": ["架田", "葑田", "漂浮模块", "可拼合农田"], "note": "田脱离土地成为可漂浮、可移动、可拼合的木架模块。“田”字划格不依赖固定地基的罕见实例——当载体可以移动，格网划分本身即为田的全部构成条件。", "text": "", "img": "social_16.jpg", "hall": "C4", "hub": false, "x": 5130.0, "y": 813.1, "rot": 2.49, "w": 142}, {"id": "social-17", "archive": "social", "title": "阡陌", "author": "", "quote": "", "year": -220, "era": "秦汉", "eraIdx": 1, "eraText": "先秦", "source": "《史记·商君列传》《汉书·食货志》", "desc": "《史记·商君列传》：“为田开阡陌封疆。”南北曰阡、东西曰陌，田间道路兼作交通、灌溉与地界；陶渊明《桃花源记》“阡陌交通，鸡犬相闻”。", "tags": ["阡陌", "开阡陌封疆", "田间道路", "负形格线"], "note": "田块为实、道路为虚，虚线框定实形。阡陌是“田”字十字笔画的实地放大——道路本身就是格网线，商鞅“开阡陌封疆”即以重画格线的方式重新划定田界。", "text": "", "img": "social_17.jpg", "hall": "C3", "hub": false, "x": 1164.3, "y": 841.9, "rot": 0.44, "w": 152}, {"id": "social-18", "archive": "social", "title": "区田法", "author": "", "quote": "", "year": -100, "era": "秦汉", "eraIdx": 1, "eraText": "汉代", "source": "《氾胜之书》；《齐民要术》引录", "desc": "《氾胜之书》载区田（区种）法：不耕旁地，将田划分为长条或方形小区（“区”），区内深耕、集中水肥；“丁男女治十亩，至秋收，可支五年之食”。", "tags": ["区田", "区种法", "小区耕作", "氾胜之书"], "note": "把整块田再切分为密集小区，逐区深耕精管。格网在此成为耕作方法本身——方格不只是所有权与地界的划分，也是劳作投入与计量的单位。", "text": "", "img": "social_18.jpg", "hall": "C5", "hub": false, "x": 1170.1, "y": 1155.5, "rot": 2.25, "w": 132}, {"id": "social-19", "archive": "social", "title": "都江堰", "author": "", "quote": "", "year": -256, "era": "先秦", "eraIdx": 0, "eraText": "四川", "source": "《史记·河渠书》《华阳国志》；都江堰（世界文化遗产，2000）", "desc": "秦蜀守李冰凿离堆、分岷江：鱼嘴分水、飞沙堰泄洪排沙、宝瓶口控流引水，无坝引水，“深淘滩、低作堰”六字诀刻石传世；灌区至今逾千万亩。", "tags": ["都江堰", "四六分水", "无坝引水"], "note": "“四六分水、二八分沙”以地形导流，分水角度由水势计算得出。渠系的分水几何直接决定下游灌区田块的排布走向——水网的格网与田网的格网上下游贯通。", "text": "", "img": "social_19.jpg", "hall": "C4", "hub": false, "x": 291.8, "y": 1150.8, "rot": 1.83, "w": 132}, {"id": "social-20", "archive": "social", "title": "灵渠", "author": "", "quote": "", "year": -214, "era": "秦汉", "eraIdx": 1, "eraText": "广西", "source": "《史记》《汉书》；广西兴安灵渠（世界灌溉工程遗产，2018）", "desc": "秦始皇为平岭南凿灵渠，沟通湘江与漓江；渠设铧嘴分水、大小天平溢流，陡门（唐代完善）分段蓄水；2018年列入世界灌溉工程遗产。", "tags": ["灵渠", "陡门", "三七分派"], "note": "铧嘴“三七分派”（三分入漓、七分归湘）以固定比例分水；数十座陡门分段蓄水、逐级启闭。运河把灌溉水源引入岭南垦区，方格田制随水系进入新流域。", "text": "", "img": "social_20.jpg", "hall": "C4", "hub": false, "x": 1397.2, "y": 820.4, "rot": 1.12, "w": 142}, {"id": "social-21", "archive": "social", "title": "郑国渠", "author": "", "quote": "", "year": -246, "era": "先秦", "eraIdx": 0, "eraText": "陕西", "source": "《史记·河渠书》《汉书·沟洫志》；郑国渠（世界灌溉工程遗产，2016）", "desc": "韩水工郑国主持，“凿泾水自中山西邸瓠口为渠……并北山东注洛三百余里”，溉“泽卤之地”四万余顷，“秦以富强，卒并诸侯”；泾水高含沙量反成淤灌之利，“且溉且粪”。", "tags": ["郑国渠", "且溉且粪", "关中灌区"], "note": "渠道为经、田畦为纬，关中平原的方格田网以渠系为骨架排布。八百里秦川的田块走向至今仍循秦渠故道——水道的方向决定了格网的方向。", "text": "", "img": "social_21.jpg", "hall": "C4", "hub": false, "x": 551.4, "y": 1167.5, "rot": -1.38, "w": 132}, {"id": "social-22", "archive": "social", "title": "坎儿井", "author": "", "quote": "", "year": -100, "era": "秦汉", "eraIdx": 1, "eraText": "新疆", "source": "新疆吐鲁番坎儿井（全国重点文物保护单位）", "desc": "吐鲁番盆地地下引水系统：竖井定位、暗渠输水、明渠出流、涝坝蓄水；竖井口沿暗渠线等距排布于戈壁，总长约五千公里。", "tags": ["坎儿井", "竖井点阵", "暗渠"], "note": "地表仅见等距排列的竖井土墩，水在地下暗渠中按固定间距设取水点——地下的线性水道与地表的等距点阵共同支撑绿洲农田的格网灌溉。", "text": "", "img": "social_22.jpg", "hall": "C4", "hub": false, "x": 1397.7, "y": 1113.4, "rot": -2.0, "w": 132}, {"id": "social-23", "archive": "social", "title": "芍陂", "author": "", "quote": "", "year": -600, "era": "先秦", "eraIdx": 0, "eraText": "安徽寿县", "source": "《汉书·循吏传》《水经注》；安徽寿县安丰塘（世界灌溉工程遗产，2015）", "desc": "春秋楚相孙叔敖主持修建，今名安丰塘，“陂径百里，灌田万顷”，是中国现存最古老的蓄水灌溉工程；2015年列入世界灌溉工程遗产。", "tags": ["芍陂", "孙叔敖", "陂塘蓄水"], "note": "陂塘蓄水、渠系引灌，下游田块按渠道分格。“陂”“田”“塘”“渠”共同构成一组水田系统的汉字谱系——每个字对应一种水利工程类型，蓄水面是格网田的水源容器。", "text": "", "img": "social_23.jpg", "hall": "C4", "hub": false, "x": 147.8, "y": 1036.5, "rot": 2.09, "w": 142}, {"id": "social-24", "archive": "social", "title": "冬水田", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "川渝黔", "source": "《王祯农书》农桑通诀；川渝丘陵农区方志", "desc": "西南丘陵区秋收后关水越冬的稻田，“蓄住一冬水、保住来年栽”；水面如镜，兼有蓄水、保墒、防虫、养萍之效。", "tags": ["冬水田", "关水越冬", "季节更替"], "note": "秋收后格内介质由稻株切换为水体，田的方格边界不变而内容物随季节更换——同一格网的季节性换装，蓄水与防虫的功能在“空格”状态下照常运行。", "text": "", "img": "social_24.jpg", "hall": "C4", "hub": false, "x": 5847.9, "y": 821.0, "rot": -1.3, "w": 132}, {"id": "social-25", "archive": "social", "title": "中国农民丰收节", "author": "", "quote": "", "year": 2018, "era": "当代", "eraIdx": 7, "eraText": "全国", "source": "《国务院关于同意设立“中国农民丰收节”的批复》（2018）", "desc": "2018年国务院批复设立，为首个国家层面专门为农民设立的节日，定于每年秋分日；主会场设于田间地头，各地晒秋、赛农事、庆五谷丰登。", "tags": ["丰收节", "秋分", "国家节庆", "田间庆典"], "note": "庆典地点固定在田块现场而非广场剧场——田的物理空间成为国家仪式的场地本体，农事竞赛（割稻、捆谷）直接在格网田块内进行。", "text": "", "img": "social_25.jpg", "hall": "C6", "hub": false, "x": 7491.1, "y": 992.4, "rot": -1.16, "w": 132}, {"id": "social-26", "archive": "social", "title": "二月二龙抬头", "author": "", "quote": "", "year": 1600, "era": "元明清", "eraIdx": 5, "eraText": "全国", "source": "《帝京景物略》《中华全国风俗志》", "desc": "农历二月初二，苍龙七宿于东方夜空初升，又值惊蛰前后、春耕将启；民间理发“剃龙头”、以草木灰在院中“围粮囤”“引钱龙”。", "tags": ["龙抬头", "星象农时", "围粮囤", "灰线画格"], "note": "以草木灰在地面撒出仓囤图形，灰线即图形边界——以线条划分地面的图形行为与田字划界同一方法；“龙—雨—田”是民间年画、剪纸中最稳定的符号组合。", "text": "", "img": "social_26.jpg", "hall": "C6", "hub": false, "x": 5561.5, "y": 1184.4, "rot": -0.88, "w": 132}, {"id": "social-27", "archive": "social", "title": "社日", "author": "", "quote": "", "year": -500, "era": "先秦", "eraIdx": 0, "eraText": "全国", "source": "《荆楚岁时记》《东京梦华录》；王驾《社日》；鲁迅《社戏》", "desc": "立春后第五个戊日为春社（祭土神祈谷）、立秋后第五个戊日为秋社（以新谷报赛）；社日饮酒分肉、演社戏。王驾《社日》：“桑柘影斜春社散，家家扶得醉人归。”", "tags": ["春社秋社", "土地神", "社戏"], "note": "春祈秋报的时间循环以田的产出为基准，社树、社坛立于田畔——土地神信仰与田块边界的空间认定相互绑定，祭祀周期与农时周期完全重合。", "text": "", "img": "social_27.jpg", "hall": "C6", "hub": false, "x": 179.8, "y": 1105.7, "rot": 0.44, "w": 142}, {"id": "social-28", "archive": "social", "title": "开秧门", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "西南稻区", "source": "贵州、云南、四川稻区民俗志", "desc": "插秧首日，由寨老或家长携酒肉至田头祭“秧神”，念祝词、拔第一把秧、喝“开秧酒”，宣告插秧开始；忌说不吉之语，主家互请帮工形成“换工”网络。", "tags": ["开秧门", "秧神", "换工"], "note": "“门”的用语把无界田面当作有启闭边界的空间——田的边界在仪式语言中被人格化。换工制度使插秧成为社群劳动力调度节点，仪式与协作在田头同时启动。", "text": "", "img": "social_28.jpg", "hall": "C6", "hub": false, "x": 5331.1, "y": 973.7, "rot": -1.75, "w": 142}, {"id": "social-29", "archive": "social", "title": "祭田神·田公田母", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "南方稻区", "source": "南方稻区民俗志；各地土地庙遗存", "desc": "农人在田角立小石龛、田头插香，祭“田公田母”（主管田地的对偶神）及五谷神、秧神，春祈秋报；小庙不过尺许，香火随农时点起又熄灭。", "tags": ["田公田母", "田头神龛", "田角"], "note": "神圣空间压缩进田块的一角：一块石头、三炷香即完成田界的神圣性标记。方形耕作单元的四角保留非生产性符号，与图幅四角安置图例的制图惯例形式相同。", "text": "", "img": "social_29.jpg", "hall": "C6", "hub": false, "x": 5132.0, "y": 1182.1, "rot": 1.93, "w": 142}, {"id": "social-30", "archive": "social", "title": "昂玛突·长街宴", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "哈尼族", "source": "云南红河州哈尼族民俗志（昂玛突为国家级非遗）", "desc": "哈尼村寨岁首祭寨神林（昂玛突），全寨按户出菜、沿村道摆“长街宴”：数百张方桌首尾相连可延绵数百米，共祭共食、议村事。", "tags": ["长街宴", "昂玛突", "方桌单元"], "note": "数百张同规格方桌沿街道线性首尾相连——重复单元的一维排列与田块的二维排列同一逻辑。道路一年一度被宴席占用，田埂村道的线性空间改变用途。", "text": "", "img": "social_30.jpg", "hall": "C6", "hub": false, "x": 5455.8, "y": 952.5, "rot": 1.23, "w": 152}, {"id": "social-31", "archive": "social", "title": "二十四节气", "author": "", "quote": "", "year": -139, "era": "秦汉", "eraIdx": 1, "eraText": "全国", "source": "《淮南子·天文训》《月令七十二候集解》；联合国非遗名录（2016）", "desc": "《淮南子·天文训》首次完整记载二十四节气：以太阳周年运动均分黄道为二十四段，“五日一候、三候一气”；2016年列入联合国人类非物质文化遗产名录。", "tags": ["节气", "农时", "历法分段", "时间网格"], "note": "太阳年被均分为二十四段，每段对应一组农事指令——时间被切成与田块对应的“段落”。历法的分段与田块的分割共用同一划分逻辑，2022年冬奥开幕式以节气做倒计时，完成了这一时间网格的现代转译。", "text": "", "img": "social_31.jpg", "hall": "C6", "hub": false, "x": 1345.7, "y": 963.2, "rot": -0.79, "w": 132}, {"id": "social-32", "archive": "social", "title": "薅草锣鼓", "author": "", "quote": "", "year": 1800, "era": "元明清", "eraIdx": 5, "eraText": "土家族、巴渝", "source": "湖北恩施、湖南湘西薅草锣鼓（国家级非遗，2008）", "desc": "集体薅秧除草时，田头“一锣一鼓”歌师领唱、众人接腔，以“穿号子”“联八句”等曲牌统一步幅与进度；“一鼓催三工”，歌声起处，田块齐动。", "tags": ["薅草锣鼓", "领和结构", "一鼓催三工"], "note": "鼓点统一步幅、领唱与帮腔的呼应控制进度——声音在田块上空组织集体动作，歌声覆盖多大田面，进度就推进到哪里。田的空间范围与声音的覆盖范围一致。", "text": "", "img": "social_32.jpg", "hall": "C6", "hub": false, "x": 5806.5, "y": 1269.2, "rot": 0.86, "w": 162}, {"id": "social-33", "archive": "social", "title": "秧歌", "author": "", "quote": "", "year": 1200, "era": "宋", "eraIdx": 4, "eraText": "北方汉族", "source": "《武林旧事·舞队》；各地秧歌（国家级非遗名录）", "desc": "源于插秧劳作之歌的节庆歌舞：舞者持扇、帕、伞、棒，“扭、浪、逗、俏”四字为舞诀；昌黎地秧歌、胶州秧歌、海阳秧歌、陕北秧歌均列入国家级非遗。", "tags": ["秧歌", "插秧舞步", "进三退一"], "note": "舞步“进三退一”的节奏来自插秧的退步栽植——田间的劳作语法被节庆回收为广场的表演语法，秧歌之名直接保存了动作来源。", "text": "", "img": "social_33.jpg", "hall": "C6", "hub": false, "x": 4468.1, "y": 1011.1, "rot": 1.4, "w": 162}, {"id": "social-34", "archive": "social", "title": "田歌", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "江南稻区", "source": "上海青浦田山歌（国家级非遗，2006）；江浙稻区田歌", "desc": "插秧、耥稻、车水时唱的山歌，以上海青浦田山歌为代表：头歌（领唱）高腔盘旋、嘹歌与和声低音铺陈，多声部结构数百年口传不辍。", "tags": ["田歌", "多声部", "青浦田山歌"], "note": "空旷水田无遮蔽、水面反射的声学条件塑造了高腔长调——田的空间属性直接决定歌种的发声形制，歌种之名（田歌、田山歌）即标明其发生场所。", "text": "", "img": "social_34.jpg", "hall": "C6", "hub": false, "x": 5843.0, "y": 972.2, "rot": 1.65, "w": 162}, {"id": "social-35", "archive": "social", "title": "花鼓戏", "author": "", "quote": "", "year": 1700, "era": "元明清", "eraIdx": 5, "eraText": "湖南", "source": "湖南花鼓戏（国家级非遗，2008）", "desc": "从“对子花鼓”（一旦一丑、田头小调）发展为地方小戏；《打铜锣》《补锅》以农事与手艺入戏，声腔“川调”“打锣腔”保留田歌呼吸法。", "tags": ["花鼓戏", "对子花鼓", "田头小调"], "note": "一旦一丑的对子格式来自田间对唱的二人结构，声腔换气位置仍保留薅秧号子的呼吸法——从田头小调到地方小戏的演化路径在剧种内部留有完整痕迹。", "text": "", "img": "social_35.jpg", "hall": "C6", "hub": false, "x": 5670.9, "y": 1316.7, "rot": -0.9, "w": 152}, {"id": "social-36", "archive": "social", "title": "耕读传家", "author": "", "quote": "", "year": 1400, "era": "元明清", "eraIdx": 5, "eraText": "全国", "source": "各地民居楹联匾额；徽州、晋中木雕彩绘遗存", "desc": "“耕读传家久，诗书继世长”——以楹联、匾额、木雕、剪纸等形式流传于民居；画面常作对半构图：一边是犁田稻浪，一边是灯下书卷。", "tags": ["耕读传家", "对半构图", "楹联匾额"], "note": "“田”作为构图的一半进入家宅正厅：左犁右灯、上田下案，二元并置是民间美术的固定构图法。田的形象经匾额木雕进入居住空间，是田进入家宅图像系统的礼制通道。", "text": "", "img": "social_36.jpg", "hall": "C6", "hub": false, "x": 5545.5, "y": 883.5, "rot": 0.43, "w": 142}, {"id": "social-37", "archive": "social", "title": "年画《男十忙》", "author": "", "quote": "", "year": 1700, "era": "元明清", "eraIdx": 5, "eraText": "山东潍县", "source": "山东潍坊杨家埠木版年画（国家级非遗）", "desc": "杨家埠（潍县）木版年画《男十忙》：以十格连环构图描绘耕、种、耪、割、打、晒等全年农事，妇孺观图即可知农时；套色木版印制。", "tags": ["男十忙", "十格连环", "套色木版", "农事分段"], "note": "全年农事切分为十格，一格一事、顺序排满——农时流程的格网式分段叙事，格与格之间的时间跳跃由观者的农事常识补全。与《女十忙》（纺织）成对，一图记录性别化的劳动分工。", "text": "", "img": "social_37.jpg", "hall": "C5", "hub": false, "x": 5554.8, "y": 1316.3, "rot": -1.95, "w": 152}, {"id": "social-38", "archive": "social", "title": "农谚", "author": "", "quote": "", "year": -100, "era": "秦汉", "eraIdx": 1, "eraText": "全国", "source": "《氾胜之书》《齐民要术》所引古农谚；各地农谚汇编", "desc": "以对仗、押韵压缩千年物候观测：“清明前后，种瓜点豆”“春争日，夏争时”“谷雨下秧，大致无妨”——节气与农事在谚语中一一对应。", "tags": ["农谚", "物候口诀", "节气农事"], "note": "七字句同时包含时间、动作、对象与容错提示——时间的分段与田的作业在口诀中一一绑定，是农时知识以最低成本口传的编码方式。", "text": "", "img": "social_38.jpg", "hall": "C5", "hub": false, "x": 1748.4, "y": 1048.7, "rot": 0.8, "w": 132}, {"id": "social-39", "archive": "social", "title": "《御制耕织图》", "author": "", "quote": "", "year": 1696, "era": "元明清", "eraIdx": 5, "eraText": "清代", "source": "康熙《御制耕织图》（1696）；焦秉贞绘", "desc": "康熙三十五年（1696）焦秉贞奉敕绘《御制耕织图》：耕21图、织24图共46幅，康熙帝亲撰序文并题诗；木刻敷彩刊行，后有雍正本、翻刻本及瓷器、织绣再创作。", "tags": ["耕织图", "宫廷版画", "46幅分段", "农事图像标准化"], "note": "耕与织的全流程被定格为46幅统一尺幅的画面，每幅一格一诗——“一格一事”的编排使农事图像第一次获得宫廷刊刻的标准格式，此后翻刻、摹绘、移植到瓷器织绣，田作图像循此版本批量传播。", "text": "", "img": "social_39.jpg", "hall": "C5", "hub": true, "x": 5393.7, "y": 1257.0, "rot": 0.85, "w": 152}, {"id": "social-40", "archive": "social", "title": "耕田", "author": "", "quote": "", "year": 1600, "era": "元明清", "eraIdx": 5, "eraText": "稻作区", "source": "《氾胜之书》《齐民要术》；敦煌莫高窟牛耕壁画", "desc": "以牛挽犁翻耕板田：人扶犁、牛拉辕，“二牛抬杠”或独牛挽犁，犁铧翻起泥浪，行进间开出笔直或螺旋的犁沟；春耕为农事年度之始。", "tags": ["耕田", "犁铧", "犁沟"], "note": "犁沟以平行线记录行进顺序，田面在翻耕中被重新划分——每一季耕作都是田块内部表面的重新划格，人、牛、犁三点构成的动力结构千年未变。", "text": "", "img": "social_40.jpg", "hall": "C5", "hub": false, "x": 5142.4, "y": 1348.4, "rot": -2.0, "w": 142}, {"id": "social-41", "archive": "social", "title": "耙田", "author": "", "quote": "", "year": 1600, "era": "元明清", "eraIdx": 5, "eraText": "稻作区", "source": "王祯《农书》农器图谱", "desc": "犁后以耙碎土、平整田面：人立耙上加压，牛力拖行，钉齿过处泥块碎解；耙后灌水，田面如镜，方可插秧。", "tags": ["耙田", "碎土平田", "钉齿耙"], "note": "犁（粗划）之后耙（细整），最终交付可蓄水的平整表面——方格田对单元内部表面有严格的平整度要求，是格网单元的表面处理工序。", "text": "", "img": "social_41.jpg", "hall": "C5", "hub": false, "x": 5250.6, "y": 1320.9, "rot": -2.59, "w": 142}, {"id": "social-42", "archive": "social", "title": "插秧", "author": "", "quote": "", "year": 1600, "era": "元明清", "eraIdx": 5, "eraText": "稻作区", "source": "《天工开物·乃粒》；布袋和尚《插秧偈》", "desc": "弯腰、退步、分行插植秧苗：农人左手分秧、右手插秧，随秧线倒退而进；布袋和尚偈云：“手把青秧插满田，低头便见水中天。”", "tags": ["插秧", "退步向前", "分行成列"], "note": "秧苗等距、分行、成列——人以身体在格网上逐行布点，是田字格被“填格”的原始操作。", "text": "", "img": "social_42.jpg", "hall": "C5", "hub": false, "x": 5623.8, "y": 1197.0, "rot": -1.67, "w": 152}, {"id": "social-43", "archive": "social", "title": "收割", "author": "", "quote": "", "year": 1600, "era": "元明清", "eraIdx": 5, "eraText": "稻麦区", "source": "《天工开物·乃粒》；各地农事影像档案", "desc": "以镰刀割稻束稿、原地晾晒成铺：收割队伍斜线推进，田面从金黄渐变为茬白；“颗粒归仓”的伦理要求连掉落的穗也要拾起。", "tags": ["收割", "镰刀", "颗粒归仓"], "note": "收割队伍斜线推进，田面从满格金黄衰减为空格茬白——方块田从满格到空格的过程在数日内可见地完成，“颗粒归仓”是格内不留残余的收获规则。", "text": "", "img": "social_43.jpg", "hall": "C5", "hub": false, "x": 5744.6, "y": 1159.7, "rot": -0.8, "w": 152}, {"id": "social-44", "archive": "social", "title": "田字格·习字方界", "author": "", "quote": "", "year": 1200, "era": "宋", "eraIdx": 4, "eraText": "蒙学传统", "source": "《字学举隅》；传统蒙学书法教材", "desc": "以“田”字形划出四方格，十字界格内习字：上留天、下留地、左右留白；铅笔描红入蒙，开笔先描田字格里的“上大人”。", "tags": ["田字格", "九宫格", "习字法", "界格"], "note": "字的中宫、四角、间架全部由“井”字分划定位——田字格把字的间架问题转化为格网定位问题，方格稿纸、米字回宫格由此衍出，是流通最广的田字形界面。", "text": "", "img": "social_44.jpg", "hall": "C1", "hub": true, "x": 4117.0, "y": 969.9, "rot": -2.47, "w": 142}, {"id": "social-45", "archive": "social", "title": "九宫格·洛书幻方", "author": "", "quote": "", "year": -500, "era": "先秦", "eraIdx": 0, "eraText": "先秦", "source": "《周易·系辞上》；《数书九章》", "desc": "“戴九履一、左三右七、二四为肩、六八为足、五居中央”——三阶幻方藏于洛书，其方格即田字之三行三列：四正、四隅、一中宫。", "tags": ["九宫格", "洛书", "三阶幻方"], "note": "三行三列、行列对角和皆十五——一格化九格、中宫居中的分格法沿用至版式与规划，是“田”字两级扩展的数理定式。", "text": "", "img": "social_45.jpg", "hall": "C2", "hub": false, "x": 330.5, "y": 1048.5, "rot": -1.22, "w": 162}, {"id": "social-46", "archive": "social", "title": "印纹陶·方格纹", "author": "", "quote": "", "year": -1000, "era": "先秦", "eraIdx": 0, "eraText": "商周—战国", "source": "江西吴城遗址、福建昙石山遗址出土印纹陶；1978年“江南地区印纹陶问题学术讨论”定名“几何印纹陶”", "desc": "南方地区流行几何印纹硬陶：以刻有方格、米字、回纹、席纹的陶拍在陶坯上拍印纹样，方格纹最常见；江西吴城、福建昙石山等遗址出土密集。", "tags": ["印纹陶", "方格纹", "陶拍", "四方连续"], "note": "一枚刻格陶拍连续压印坯体，方格单元四方连续铺满器身——以模具复制方格的最早批量实践之一，方格纹的连续排布与田块的邻接铺展共用同一拼接规则。", "text": "", "img": "social_46.jpg", "hall": "C2", "hub": false, "x": 338.2, "y": 886.1, "rot": 0.26, "w": 132}, {"id": "social-47", "archive": "social", "title": "瓦当·方格地纹", "author": "", "quote": "", "year": -200, "era": "秦汉", "eraIdx": 1, "eraText": "战国—汉", "source": "秦雍城、临淄汉瓦当出土遗存；中国国家博物馆藏品", "desc": "秦汉瓦当当面常以方格、米字、回纹、四叶作“地纹”，中心再置一动物或文字；成行覆列于屋檐之下。", "tags": ["瓦当", "方格地纹", "檐下序列"], "note": "每片瓦当为一格、一行即一列——方格纹的单体沿屋檐线性排列成带，田字纹样在建筑构件上以序列化的方式排布，中心与地纹的“主纹—地格”关系沿用至后世装饰。", "text": "", "img": "social_47.jpg", "hall": "C2", "hub": false, "x": 1712.9, "y": 875.2, "rot": -2.22, "w": 162}, {"id": "social-48", "archive": "social", "title": "方格窗棂", "author": "", "quote": "", "year": 1100, "era": "宋", "eraIdx": 4, "eraText": "全国", "source": "徽州、晋中民居遗存；《营造法式》小木作", "desc": "传统民居木窗以直棂构成方格网：“井字格”横竖均分、“十字格”单井一窗、“冰裂”自由演化——阳光经格网在白墙上投下方格阴影。", "tags": ["窗棂", "井字格", "格网投影"], "note": "阳光每穿一格，白墙多一个方格阴影——窗棂是透光的分格界面，棂条的疏密即格网的密度，投影纹样随日照角度在一天内连续变化。", "text": "", "img": "social_48.jpg", "hall": "C2", "hub": false, "x": 4429.1, "y": 828.4, "rot": 0.85, "w": 152}, {"id": "social-49", "archive": "social", "title": "围棋", "author": "", "quote": "", "year": -500, "era": "先秦", "eraIdx": 0, "eraText": "春秋", "source": "《弈旨》《忘忧清乐集》；围棋（人类非物质文化遗产，2017）", "desc": "围棋以纵横各十九道、共三百六十一个交叉点的方格网为盘，黑白子落于交点；2017年列入人类非物质文化遗产。", "tags": ["围棋", "361交点", "方格对弈"], "note": "19×19 道是“井”字分格的极限扩展——子落在交叉点而非格内，“占点”与“占田”在格网上同位。方格盘面无字无图，全部内容由落子位置定义。", "text": "", "img": "social_49.jpg", "hall": "C2", "hub": false, "x": 514.2, "y": 1019.7, "rot": 1.2, "w": 162}, {"id": "social-50", "archive": "social", "title": "印章·印面田字格", "author": "", "quote": "", "year": -200, "era": "秦汉", "eraIdx": 1, "eraText": "战国—当代", "source": "《汉印分韵》《十钟山房印举》", "desc": "汉印方形印面以“田”字分划四格（四字印）、“井”字分九格（九叠篆官印），每格置一字；“日字格”“田字格”为印章章法的基本界格。", "tags": ["印章", "九叠篆", "界格章法"], "note": "方寸印面以“田”“井”字分格置字，字的疏密、挪让均在界格内完成——四字顺读、回文读、交叉读的章法都以田字格为构图骨架，界格是篆刻排布的隐形依据。", "text": "", "img": "social_50.jpg", "hall": "C1", "hub": true, "x": 1511.9, "y": 813.1, "rot": 0.76, "w": 162}, {"id": "social-51", "archive": "social", "title": "雕版印刷·界栏", "author": "", "quote": "", "year": 868, "era": "隋唐", "eraIdx": 3, "eraText": "唐—清", "source": "敦煌《金刚经》刻本（868）；宋元明清朝刻本", "desc": "唐咸通九年（868）刊《金刚经》扉页已用方格界栏；宋元至明清的雕版书叶四周以“版框”“界行”划格，每格一字。", "tags": ["雕版", "版框", "界行", "行格"], "note": "版框界行划格、每字一格——田字格从习字纸放大为整页版面，“田”的方格分划成为出版版式的基本框架，宋版书的行格定制与“纸背格线”由此定型。", "text": "", "img": "social_51.jpg", "hall": "C2", "hub": false, "x": 3141.6, "y": 1008.0, "rot": 0.8, "w": 162}, {"id": "social-52", "archive": "social", "title": "青花·锦地纹", "author": "", "quote": "", "year": 1400, "era": "元明清", "eraIdx": 5, "eraText": "明清", "source": "景德镇御窑厂遗址；故宫博物院明清官窑藏品", "desc": "明清青花瓷常见“锦地纹”——以青花线勾出方格、米字、回纹等小方阵作地，留白处绘主纹；方格之内又套方格。", "tags": ["青花", "锦地纹", "格内套格"], "note": "方中套方、格内生格——“田”字的嵌套复制在瓷面地纹上完成。地纹以格网铺满底部衬托主纹，“主纹—地格”的主次分层是图案排布的固定语法。", "text": "", "img": "social_52.jpg", "hall": "C2", "hub": false, "x": 5661.6, "y": 804.2, "rot": -0.7, "w": 132}, {"id": "social-53", "archive": "social", "title": "蓝印花布·方格", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "汉族", "source": "江苏南通蓝印花布（国家级非遗，2008）", "desc": "以油纸刻版、黄豆粉防染：“药斑版”刻出方格、米字、八角、井字纹样，蓝靛浸染后白花蓝地——方格是最常见的基础花型之一。", "tags": ["蓝印花布", "药斑版", "防染", "白格蓝地"], "note": "白色方格是防染剂留出的负形——格网以“空”显形，与青花锦地纹的“实”格互补。刻版、刮浆、浸染三道工序决定方格边缘的渗化肌理，是民间对“格”的批量印制法。", "text": "", "img": "social_53.jpg", "hall": "C2", "hub": false, "x": 5466.0, "y": 1127.9, "rot": 0.74, "w": 162}, {"id": "social-54", "archive": "social", "title": "壮锦·通经断纬", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "壮族", "source": "广西壮族自治区织锦技艺（国家级非遗）", "desc": "壮锦以棉线为经、丝线为纬，“通经断纬”织出方格、“十”字、米字、回纹等“田”字族纹样；几何小方格重复排列构成大花。", "tags": ["壮锦", "通经断纬", "方格花"], "note": "经线为竖、纬线为横，方格在经纬交点生成——“田”字族纹样直接来自织机的经纬设定，布面上的方格与大地上的田块共用“纵横交织成格”的构成方法。", "text": "", "img": "social_54.jpg", "hall": "C2", "hub": false, "x": 5132.4, "y": 1006.0, "rot": 1.95, "w": 142}, {"id": "social-55", "archive": "social", "title": "苗绣·井田回三形", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "苗族", "source": "贵州黔东南苗绣（国家级非遗，2006）；《苗族古歌》", "desc": "苗绣以平绣、辫绣、打籽绣、破线绣等针法，绣出连续方格、八角星、井字、回纹——“井”“田”“回”三种基础形是几乎所有花样的底盘。", "tags": ["苗绣", "井田回三形", "底盘纹样"], "note": "方格与回纹的旋转、嵌合构成花样的基本骨架——井、田、回三形是不依赖画稿的世代传习底格，复杂花样由这三形变形拼合而成。", "text": "", "img": "social_55.jpg", "hall": "C2", "hub": true, "x": 5222.8, "y": 1119.3, "rot": -0.89, "w": 132}, {"id": "social-56", "archive": "social", "title": "罗·绞经方孔", "author": "", "quote": "", "year": -200, "era": "秦汉", "eraIdx": 1, "eraText": "商周—汉", "source": "长沙马王堆汉墓素纱襌衣；《释名·释采帛》", "desc": "罗为绞经织物：地经与绞经交替绞扭，纬线被绞经固定，织物表面形成稳定方孔（纱孔）；马王堆汉墓素纱襌衣重不足五十克。《释名·释采帛》：“罗，文罗疏也。”", "tags": ["罗", "绞经", "方孔组织", "纱孔"], "note": "经线为竖、纬线为横、绞点为十字结——绞经罗的织物结构天然生成规则方孔阵，一块罗的纱孔排布与田字格的骨架完全同构，格网在织物中以“孔”的形态存在。", "text": "", "img": "social_56.jpg", "hall": "C2", "hub": false, "x": 1164.5, "y": 1006.3, "rot": -2.08, "w": 142}, {"id": "social-57", "archive": "social", "title": "唐长安里坊", "author": "", "quote": "", "year": 700, "era": "隋唐", "eraIdx": 3, "eraText": "唐", "source": "白居易《登观音台望城》；《长安志》；唐长安城遗址", "desc": "隋大兴—唐长安以朱雀大街为轴，全城划一百零八坊，坊墙封闭、宵禁启闭；白居易《登观音台望城》：“百千家似围棋局，十二街如种菜畦。”", "tags": ["里坊制", "棋盘城市", "种菜畦"], "note": "白居易以棋局、菜畦直接类比里坊——井田格网转译为都城尺度有唐诗自证。一百零八坊即一百零八个封闭单元格，宵禁使格网附带启闭的时间属性。", "text": "", "img": "social_57.jpg", "hall": "C2", "hub": false, "x": 3171.3, "y": 890.3, "rot": 0.6, "w": 152}, {"id": "social-58", "archive": "social", "title": "棋盘街", "author": "", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "北京", "source": "《日下旧闻考》；北京正阳门棋盘街", "desc": "北京正阳门前有“棋盘街”，因街道纵横垂直、状如棋盘得名，明清两代为商贾云集之地；中国城市以“棋盘”“菜畦”命名格网街道的实例。", "tags": ["棋盘街", "格网街道", "街道命名"], "note": "以“棋盘”为格网街道命名，说明方格城市形态在民间认知中被归入棋盘、田畴的同类——里坊制消亡后格网作为城市形态留存，名称记录了从田到街的形态迁移。", "text": "", "img": "social_58.jpg", "hall": "C2", "hub": false, "x": 5642.0, "y": 1028.7, "rot": -2.04, "w": 132}, {"id": "social-59", "archive": "social", "title": "稻田画", "author": "", "quote": "", "year": 1993, "era": "当代", "eraIdx": 7, "eraText": "日本青森 / 中国", "source": "日本青森田舍馆村稻田画（1993— ）；中国沈阳锡伯龙地稻田画", "desc": "日本青森县田舍馆村自1993年起以紫、黄、绿、白等色叶稻“作画”，观光塔俯瞰成图，每年一作、随生长变色；沈阳、桂林等地引入后本土化。", "tags": ["稻田画", "色叶稻", "俯瞰阅读"], "note": "不同色叶稻分区插植，每格赋一种颜色——田字格的单元成为配色单元，画面必须在高处才能阅读，观看方式（观光塔）是作品的组成部分。", "text": "", "img": "social_59.jpg", "hall": "C8", "hub": true, "x": 7179.1, "y": 815.5, "rot": -1.13, "w": 142}, {"id": "social-60", "archive": "social", "title": "越后妻有大地艺术祭", "author": "", "quote": "", "year": 2000, "era": "当代", "eraIdx": 7, "eraText": "日本新潟", "source": "越后妻有大地艺术祭（Echigo-Tsumari Art Triennale，2000— ）", "desc": "策展人北川富朗自2000年起在新潟越后妻有（760平方公里雪山稻田区）创办大地艺术祭：草间弥生等艺术家作品散布于农地、空屋、废校与梯田间。", "tags": ["大地艺术祭", "艺术乡建", "作品与农地共存"], "note": "作品与农地、积雪、废校直接共存，不置换农业——田从被描绘的对象（农事图、山水画）转为作品的场地与语境，是“田”进入当代艺术语境的关键节点。", "text": "", "img": "social_60.jpg", "hall": "C8", "hub": true, "x": 7566.1, "y": 820.4, "rot": 0.7, "w": 152}, {"id": "lit-2", "archive": "lit", "title": "无名氏《豳风·七月》", "author": "无名氏", "quote": "三之日于耜，四之日举趾。同我妇子，馌彼南亩，田畯至喜。", "year": -10, "era": "秦汉", "eraIdx": 1, "eraText": "先秦（西周，约前11—前8世纪）", "source": "无名氏《豳风·七月》，《诗经·国风》", "desc": "", "tags": ["农事生产", "民生疾苦"], "note": "中国文学史上最早的农事月令式书写，「于耜」「举趾」「馌彼南亩」完整呈现春耕备耕、妇子送饭田头的劳动图景，为后世田园诗写实传统之源。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 1376.3, "y": 1440.4, "rot": 1.02, "w": 162}, {"id": "lit-3", "archive": "lit", "title": "无名氏《周颂·载芟》", "author": "无名氏", "quote": "载芟载柞，其耕泽泽。千耦其耘，徂隰徂畛。", "year": -900, "era": "先秦", "eraIdx": 0, "eraText": "先秦（西周，成王之后）", "source": "无名氏《周颂·载芟》，《诗经·周颂》", "desc": "", "tags": ["农事生产", "祭祀祈年"], "note": "「千耦其耘」写出大规模集体耕作的壮阔场面，全诗由开垦、播种直写到收获祭祖，是研究西周井田制耦耕形态与籍田祭典的核心文学材料。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 189.7, "y": 1414.8, "rot": 2.07, "w": 162}, {"id": "lit-4", "archive": "lit", "title": "无名氏《小雅·甫田》", "author": "无名氏", "quote": "倬彼甫田，岁取十千。我取其陈，食我农人。自古有年。", "year": -900, "era": "先秦", "eraIdx": 0, "eraText": "先秦（西周）", "source": "无名氏《小雅·甫田》，《诗经·小雅》", "desc": "", "tags": ["祭祀祈年", "丰收喜悦"], "note": "「甫田」即大田、公田，诗歌咏周王省耕、祭田祖祈甘雨；「田」既是财富之本也是祭祀对象，体现以农立国的意识形态，与《大田》并称祈年诗双璧。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 701.9, "y": 1412.1, "rot": 0.66, "w": 152}, {"id": "lit-5", "archive": "lit", "title": "无名氏《小雅·大田》", "author": "无名氏", "quote": "有渰萋萋，兴雨祈祈。雨我公田，遂及我私。", "year": -900, "era": "先秦", "eraIdx": 0, "eraText": "先秦（西周）", "source": "无名氏《小雅·大田》，《诗经·小雅》", "desc": "", "tags": ["丰收喜悦", "农事生产", "祭祀祈年"], "note": "「雨我公田，遂及我私」是井田制下公私田关系最著名的文学表述（《孟子》论井田即引此句），「遗秉滞穗，伊寡妇之利」更写出收获场景中的温情遗风。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 404.0, "y": 1435.2, "rot": 1.77, "w": 152}, {"id": "lit-6", "archive": "lit", "title": "无名氏《魏风·伐檀》", "author": "无名氏", "quote": "不稼不穑，胡取禾三百廛兮？不狩不猎，胡瞻尔庭有县貆兮？", "year": -7, "era": "秦汉", "eraIdx": 1, "eraText": "先秦（春秋，约前7—前6世纪）", "source": "无名氏《魏风·伐檀》，《诗经·国风》", "desc": "", "tags": ["徭役赋税", "民生疾苦"], "note": "以「不稼不穑」却坐拥「三百廛」的强烈反差质问不劳而获者，「田」（禾稼）在此成为劳动果实与剥削关系的符号，开创中国诗歌的讽刺批判传统。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 1106.0, "y": 1556.5, "rot": 0.16, "w": 152}, {"id": "lit-7", "archive": "lit", "title": "无名氏《魏风·硕鼠》", "author": "无名氏", "quote": "硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。", "year": -600, "era": "先秦", "eraIdx": 0, "eraText": "先秦（春秋）", "source": "无名氏《魏风·硕鼠》，《诗经·国风》", "desc": "", "tags": ["民生疾苦", "徭役赋税", "田园向往"], "note": "以吞食黍麦的「硕鼠」喻贪残剥削者，而「乐土」「乐郊」则是田亩理想的乌托邦化表达——没有剥削的农耕乐土成为后世田园理想的最早原型之一。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 142.8, "y": 1581.4, "rot": -1.38, "w": 152}, {"id": "lit-8", "archive": "lit", "title": "无名氏《王风·黍离》", "author": "无名氏", "quote": "彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。", "year": -8, "era": "秦汉", "eraIdx": 1, "eraText": "先秦（东周初，约前8—前7世纪）", "source": "无名氏《王风·黍离》，《诗经·国风》", "desc": "", "tags": ["荒芜哀叹"], "note": "故宗庙宫室尽为禾黍，茂盛的「田」恰恰反衬亡国废墟之悲，「黍离之悲」自此成为故国之思的经典意象，农田在此被赋予深沉的历史沧桑感。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 1616.0, "y": 1384.9, "rot": 1.81, "w": 162}, {"id": "lit-9", "archive": "lit", "title": "屈原（相传）《卜居》", "author": "屈原（相传）", "quote": "宁诛锄草茅以力耕乎，将游大人以成名乎？", "year": -300, "era": "先秦", "eraIdx": 0, "eraText": "战国（约前3世纪）", "source": "屈原（相传）《卜居》，《楚辞》", "desc": "", "tags": ["隐逸", "田园向往"], "note": "在「宁……将……」的排比设问中，「诛锄草茅以力耕」被树立为与干谒权贵相对立的高洁人生选项，农耕劳作首次成为士人精神操守的象征，上接长沮桀溺，下启陶渊明。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 388.4, "y": 1564.0, "rot": -1.88, "w": 142}, {"id": "lit-10", "archive": "lit", "title": "张衡《归田赋》", "author": "张衡", "quote": "于是仲春令月，时和气清；原隰郁茂，百草滋荣。王雎鼓翼，鸧鹒哀鸣；交颈颉颃，关关嘤嘤。", "year": 150, "era": "秦汉", "eraIdx": 1, "eraText": "东汉（约公元2世纪）", "source": "张衡《归田赋》，《文选》卷十五", "desc": "", "tags": ["田园向往", "隐逸"], "note": "文学史上第一篇以「归田」为题的辞赋，将田园原野（原隰郁茂）写成远离浊世的审美对象和精神归宿，直接开启魏晋以降的田园隐逸文学传统。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 1464.0, "y": 1599.1, "rot": 0.59, "w": 162}, {"id": "lit-11", "archive": "lit", "title": "无名氏《十五从军征》", "author": "无名氏", "quote": "兔从狗窦入，雉从梁上飞。中庭生旅谷，井上生旅葵。", "year": -100, "era": "秦汉", "eraIdx": 1, "eraText": "两汉（东汉，约2—3世纪）", "source": "无名氏《十五从军征》，汉乐府", "desc": "", "tags": ["荒芜哀叹", "民生疾苦"], "note": "老兵六十五年后归家，庭院井台尽生野生谷葵——无人耕种的「田」化为最触目惊心的荒凉，以农家田园的荒废控诉兵役之酷，白描手法影响深远。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 1197.1, "y": 1446.0, "rot": 2.0, "w": 162}, {"id": "lit-12", "archive": "lit", "title": "陶渊明《归园田居·其一》", "author": "陶渊明", "quote": "羁鸟恋旧林，池鱼思故渊。开荒南野际，守拙归园田。", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋，约义熙二年（406年）", "source": "陶渊明《归园田居·其一》，《陶渊明集》", "desc": "", "tags": ["归隐田园", "田园向往"], "note": "以「羁鸟」「池鱼」反衬，点明「归园田」为全组诗主旨，是陶渊明弃官归耕的宣言书。此篇奠定中国田园诗的基本范式，「园田」自此成为与仕途相对立的精神归宿意象。", "text": "", "img": null, "hall": "C7", "hub": true, "x": 2579.9, "y": 1398.9, "rot": 1.4, "w": 132}, {"id": "lit-13", "archive": "lit", "title": "陶渊明《归园田居·其三》", "author": "陶渊明", "quote": "种豆南山下，草盛豆苗稀。晨兴理荒秽，带月荷锄归。", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋，约义熙二年（406年）", "source": "陶渊明《归园田居·其三》，《陶渊明集》", "desc": "", "tags": ["劳动体验", "农耕自适"], "note": "首次将士大夫亲身锄草的田间劳作写入诗歌，「草盛豆苗稀」的拙朴与「带月荷锄归」的诗意并存，开创以真实农耕生活为审美对象的传统，暗用杨恽「田彼南山，芜秽不治」之典而翻出新意。", "text": "", "img": null, "hall": "C7", "hub": true, "x": 2777.8, "y": 1436.6, "rot": -0.62, "w": 132}, {"id": "lit-14", "archive": "lit", "title": "陶渊明《归园田居·其四》", "author": "陶渊明", "quote": "试携子侄辈，披榛步荒墟。徘徊丘垄间，依依昔人居。井灶有遗处，桑竹残朽株。", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋，约义熙二年（406年）", "source": "陶渊明《归园田居·其四》，《陶渊明集》", "desc": "", "tags": ["荒芜哀叹", "人世沧桑"], "note": "写归田后漫游所见村落废墟、人亡物朽之景，是晋末战乱与农村凋敝的真实投影。「荒墟」「残株」之「田」意象打破田园诗一味恬静的表层，寄寓「一世异朝市」的深沉悲慨。", "text": "", "img": null, "hall": "C7", "hub": true, "x": 2203.1, "y": 1539.9, "rot": -0.57, "w": 162}, {"id": "lit-15", "archive": "lit", "title": "陶渊明《归去来兮辞》", "author": "陶渊明", "quote": "归去来兮，田园将芜胡不归？既自以心为形役，奚惆怅而独悲？", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋义熙元年（405年）", "source": "陶渊明《归去来兮辞》，《陶渊明集》卷五、《文选》", "desc": "", "tags": ["田园向往", "归隐宣言"], "note": "以「田园将芜」为呼告的理由，将田园设定为心灵的故园；后文「农人告余以春及，将有事于西畴」更把春耕纳入隐士生活图景。欧阳修称「晋无文章，惟陶渊明《归去来兮辞》一篇而已」。", "text": "", "img": null, "hall": "C7", "hub": true, "x": 2333.9, "y": 1414.3, "rot": -0.44, "w": 142}, {"id": "lit-16", "archive": "lit", "title": "陶渊明《癸卯岁始春怀古田舍二首·其二》", "author": "陶渊明", "quote": "秉耒欢时务，解颜劝农人。平畴交远风，良苗亦怀新。", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋元兴二年（403年）", "source": "陶渊明《癸卯岁始春怀古田舍二首·其二》，《陶渊明集》", "desc": "", "tags": ["自然审美", "劳动体验"], "note": "写始春日田野上远风拂苗、生意盎然之景，是亲身耕耘者方能道出的名句，苏轼赞「非古之耦耕植杖者不能道此语」。「平畴」「良苗」意象将农田本身提升为独立审美对象。", "text": "", "img": null, "hall": "C7", "hub": true, "x": 2538.6, "y": 1537.3, "rot": -0.07, "w": 162}, {"id": "lit-17", "archive": "lit", "title": "陶渊明《饮酒二十首·其五》", "author": "陶渊明", "quote": "结庐在人境，而无车马喧。问君何能尔？心远地自偏。采菊东篱下，悠然见南山。", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋，一说义熙十三年（417年）前后", "source": "陶渊明《饮酒二十首·其五》，《陶渊明集》", "desc": "", "tags": ["自然审美", "归隐田园"], "note": "东篱、南山构成田园居息的核心空间意象，「悠然」境界成为后世隐逸文学的审美典范，标志田园诗由叙事写景升入哲理化的人生境界。", "text": "", "img": null, "hall": "C7", "hub": true, "x": 2715.3, "y": 1577.9, "rot": -0.5, "w": 142}, {"id": "lit-18", "archive": "lit", "title": "陶渊明《庚戌岁九月中于西田获早稻》", "author": "陶渊明", "quote": "人生归有道，衣食固其端。孰是都不营，而以求自安？", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋义熙六年（410年）", "source": "陶渊明《庚戌岁九月中于西田获早稻》，《陶渊明集》", "desc": "", "tags": ["劳动体验", "农耕自适"], "note": "把自耕自食提升为人生根本之「道」，直陈农耕之苦而不悔，并以长沮、桀溺自期。此篇将「田」从观赏对象深化为生存论与道德论层面的人生根基，是陶渊明田园诗思想性最强的作品之一。", "text": "……\n田家岂不苦？弗获辞此难。四体诚乃疲，庶无异患干", "img": null, "hall": "C7", "hub": true, "x": 2136.0, "y": 1375.3, "rot": -1.49, "w": 162}, {"id": "lit-19", "archive": "lit", "title": "陶渊明《桃花源记》", "author": "陶渊明", "quote": "土地平旷，屋舍俨然，有良田美池桑竹之属。阡陌交通，鸡犬相闻。其中往来种作，男女衣着，悉如外人。黄发垂髫，并怡然自乐。", "year": 400, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "东晋末至刘宋初，约永初二年（421年）前后", "source": "陶渊明《桃花源记》，《陶渊明集》", "desc": "", "tags": ["桃花源理想", "田园向往"], "note": "以「良田—美池—桑竹—阡陌」构建自给自足、无赋税战乱的理想农耕社会，使「田园」意象升华为中国社会理想的文化原型，影响后世「桃源」母题历代不衰。", "text": "", "img": null, "hall": "C7", "hub": true, "x": 2349.6, "y": 1583.5, "rot": 1.56, "w": 142}, {"id": "lit-20", "archive": "lit", "title": "谢灵运《登池上楼》", "author": "谢灵运", "quote": "初景革绪风，新阳改故阴。池塘生春草，园柳变鸣禽。", "year": 500, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "南朝宋景平元年（423年）初春", "source": "谢灵运《登池上楼》，《文选》卷二十二、《谢康乐集》", "desc": "", "tags": ["自然审美", "园林逸趣"], "note": "久病初起时对园圃初春细微生机的敏锐捕捉，钟嵘《诗品》引《谢氏家录》谓「此语有神助」。此联代表谢灵运将陶渊明式的田园景物纳入精工刻画的山水诗传统，促成田园诗与山水诗的合流。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 2190.9, "y": 1752.0, "rot": 2.5, "w": 132}, {"id": "lit-21", "archive": "lit", "title": "庾信《小园赋》", "author": "庾信", "quote": "一寸二寸之鱼，三竿两竿之竹。云气荫于丛蓍，金精养于秋菊。枣酸梨酢，桃榹李薁。落叶半床，狂花满屋。名为野人之家，是谓愚公之谷。", "year": 581, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "北朝北周（约557—581年间）", "source": "庾信《小园赋》，《艺文类聚》卷六十五、《庾子山集》", "desc": "", "tags": ["田园向往", "故园之思", "荒芜哀叹"], "note": "庾信由南入北、仕宦异国而不得归，借数亩小园寄托乡关之思；「落叶半床，狂花满屋」使田园意象染上半荒芜的颓美感伤色彩，与陶渊明的主动归耕形成对照，标志田园书写从隐逸理想向身世之悲的演变。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 2393.8, "y": 1719.2, "rot": 0.85, "w": 132}, {"id": "lit-22", "archive": "lit", "title": "王维《积雨辋川庄作》", "author": "王维", "quote": "漠漠水田飞白鹭，阴阴夏木啭黄鹂。", "year": 760, "era": "隋唐", "eraIdx": 3, "eraText": "盛唐，约上元年间（760年前后），王维晚年隐居辋川时期", "source": "王维《积雨辋川庄作》", "desc": "", "tags": ["禅意田园", "田园牧歌", "水田风光"], "note": "以「水田」为画面中心，白鹭、黄鹂点缀其间，稻田劳作被提升为与「山中习静」「松下清斋」同构的禅悦境界，是辋川田园诗将农场景观审美化、禅意化的典范。首联「蒸藜炊黍饷东菑」亦写田家送饭。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3210.0, "y": 1545.0, "rot": 0.78, "w": 132}, {"id": "lit-23", "archive": "lit", "title": "王维《渭川田家》", "author": "王维", "quote": "雉雊麦苗秀，蚕眠桑叶稀。田夫荷锄至，相见语依依。", "year": 750, "era": "隋唐", "eraIdx": 3, "eraText": "盛唐，约开元（713—741）后期", "source": "王维《渭川田家》（一作《渭水田家》）", "desc": "", "tags": ["田园牧歌", "归隐向往", "田家暮归"], "note": "麦苗、田夫、牛羊、柴扉构成一幅「人皆有所归」的田家晚归图，结句「即此羡闲逸，怅然吟式微」点明田园作为仕宦倦怠者精神归宿的意义。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3705.3, "y": 1368.2, "rot": -2.5, "w": 132}, {"id": "lit-24", "archive": "lit", "title": "孟浩然《过故人庄》", "author": "孟浩然", "quote": "故人具鸡黍，邀我至田家。", "year": 750, "era": "隋唐", "eraIdx": 3, "eraText": "盛唐开元年间，隐居鹿门山时期", "source": "孟浩然《过故人庄》，《全唐诗》卷160", "desc": "", "tags": ["田园牧歌", "田家情趣", "主客欢愉"], "note": "「田家」在此是情谊与生活方式的载体，场圃、桑麻等田园意象进入宴饮话题，确立了唐诗中「田家作客」的温情范式。", "text": "……\n开轩面场圃，把酒话桑麻。", "img": null, "hall": "C7", "hub": false, "x": 3571.3, "y": 1397.9, "rot": 1.31, "w": 162}, {"id": "lit-25", "archive": "lit", "title": "孟浩然《田家元日》", "author": "孟浩然", "quote": "我年已强仕，无禄尚忧农。桑野就耕父，荷锄随牧童。田家占气候，共说此年丰。", "year": 750, "era": "隋唐", "eraIdx": 3, "eraText": "盛唐，开元十五年（727）春节", "source": "孟浩然《田家元日》", "desc": "", "tags": ["农事生产", "忧农情怀", "丰年祈盼"], "note": "以元日田家占候年丰的习俗入诗，「无禄尚忧农」把士人的用世之心寄托于田野，显示田园诗与儒家重农思想的交融。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3316.2, "y": 1392.7, "rot": -0.24, "w": 152}, {"id": "lit-26", "archive": "lit", "title": "储光羲《田家即事》", "author": "储光羲", "quote": "迎晨起饭牛，双驾耕东菑。蚯蚓土中出，田乌随我飞。", "year": 750, "era": "隋唐", "eraIdx": 3, "eraText": "盛唐，开元、天宝年间", "source": "储光羲《田家即事》", "desc": "", "tags": ["农事生产", "春耕纪实", "田园白描"], "note": "以第一人称亲历春耕，蚯蚓、田乌等田间微物入诗，真实感与恻隐心（「拨食与田乌」）兼备，是田园诗派中最贴近农作现场的作品之一。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3167.1, "y": 1373.6, "rot": -0.2, "w": 132}, {"id": "lit-27", "archive": "lit", "title": "韦应物《观田家》", "author": "韦应物", "quote": "微雨众卉新，一雷惊蛰始。田家几日闲，耕种从此起。", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "中唐，兴元元年（784）前后，韦应物任滁州刺史期间", "source": "韦应物《观田家》", "desc": "", "tags": ["农事生产", "悯农自责", "民生疾苦"], "note": "由惊蛰春耕写起，笔锋一转落到仓廪空虚、徭役未已，以刺史「方惭不耕者」的自省收束，是田园诗由审美向悯农写实过渡的关键节点。", "text": "……\n仓禀无宿储，徭役犹未已。方惭不耕者，禄食出闾里。", "img": null, "hall": "C7", "hub": false, "x": 3378.3, "y": 1676.4, "rot": -0.98, "w": 132}, {"id": "lit-28", "archive": "lit", "title": "杜甫《蚕谷行》", "author": "杜甫", "quote": "天下郡国向万城，无有一城无甲兵。焉得铸甲作农器，一寸荒田牛得耕。", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "中唐，约大历元年（766）至大历四年（769）之间", "source": "杜甫《蚕谷行》", "desc": "", "tags": ["战乱荒田", "反战理想", "悯农讽喻"], "note": "「荒田」意象直指安史乱后农业凋敝的现实，「铸甲作农器」是世界文学史上极早的「铸剑为犁」式反战表达，赋予「田」以和平理想的象征意义。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3554.6, "y": 1533.9, "rot": -0.14, "w": 132}, {"id": "lit-29", "archive": "lit", "title": "白居易《观刈麦》", "author": "白居易", "quote": "田家少闲月，五月人倍忙。夜来南风起，小麦覆陇黄。", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "中唐，元和元年（806）前后，白居易任盩厔县尉时作", "source": "白居易《观刈麦》", "desc": "", "tags": ["农事生产", "民生疾苦", "租税疾苦"], "note": "麦田丰收的喜人景象与贫妇拾穗的惨状形成强烈反差，「家田输税尽」点破赋税夺田的主题，开中唐新乐府悯农诗的先声。", "text": "……\n家田输税尽，拾此充饥肠。", "img": null, "hall": "C7", "hub": false, "x": 3110.1, "y": 1720.7, "rot": 1.29, "w": 132}, {"id": "lit-30", "archive": "lit", "title": "白居易《杜陵叟》", "author": "白居易", "quote": "杜陵叟，杜陵居，岁种薄田一顷余。三月无雨旱风起，麦苗不秀多黄死。", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "中唐，元和四年（809），白居易任左拾遗时作", "source": "白居易《杜陵叟》（《新乐府》五十首之一）", "desc": "", "tags": ["租税疾苦", "悯农讽喻", "天灾苛政"], "note": "「薄田」在旱霜之灾与长吏急敛的双重挤压下彻底破产，「十家租税九家毕，虚受吾君蠲免恩」的讽刺冷峻入骨，是新乐府「为事而作」的标本。", "text": "……\n典桑卖地纳官租，明年衣食将何如？", "img": null, "hall": "C7", "hub": false, "x": 3742.7, "y": 1531.8, "rot": 1.04, "w": 152}, {"id": "lit-31", "archive": "lit", "title": "李绅《悯农二首》", "author": "李绅", "quote": "春种一粒粟，秋收万颗子。四海无闲田，农夫犹饿死。", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "中唐，约贞元十五年（799）作", "source": "李绅《悯农二首》其一（一题《古风二首》）", "desc": "", "tags": ["悯农讽喻", "丰收悖论", "民生疾苦"], "note": "「无闲田」与「犹饿死」构成惊心动魄的悖论——土地开垦殆尽而耕者仍不免饿死，矛头直指分配制度，成为悯农诗的千古绝唱。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3375.5, "y": 1605.0, "rot": -1.56, "w": 132}, {"id": "lit-32", "archive": "lit", "title": "聂夷中《咏田家》", "author": "聂夷中", "quote": "二月卖新丝，五月粜新谷。医得眼前疮，剜却心头肉。", "year": 850, "era": "隋唐", "eraIdx": 3, "eraText": "晚唐，咸通年间前后", "source": "聂夷中《咏田家》（一作《伤田家》）", "desc": "", "tags": ["悯农讽喻", "高利贷盘剥", "民生疾苦"], "note": "以「剜肉补疮」的酷烈比喻写农民预卖田产收成的绝境，成语「剜肉补疮」由此而来；五代宰相冯道曾向后唐明宗诵此诗以谏，可见其现实影响力。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3591.5, "y": 1717.6, "rot": 2.12, "w": 162}, {"id": "lit-33", "archive": "lit", "title": "皮日休《橡媪叹》", "author": "皮日休", "quote": "山前有熟稻，紫穗袭人香。细获又精舂，粒粒如玉珰。持之纳于官，私室无仓箱。如何一石余，只作五斗量！", "year": 860, "era": "隋唐", "eraIdx": 3, "eraText": "晚唐，咸通年间（约860年代）", "source": "皮日休《橡媪叹》（《正乐府十篇》之二）", "desc": "", "tags": ["悯农讽喻", "租税疾苦", "官吏贪墨"], "note": "「熟稻」的丰饶与「橡实诳饥肠」的悲惨形成对照，揭露晚唐官仓量器作弊、一石作五斗的掠夺黑幕，是皮日休「乐府补王政之缺」主张的实践。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 3722.6, "y": 1731.5, "rot": -2.2, "w": 142}, {"id": "lit-34", "archive": "lit", "title": "范成大《四时田园杂兴六十首》", "author": "范成大", "quote": "昼出耘田夜绩麻，村庄儿女各当家。童孙未解供耕织，也傍桑阴学种瓜。", "year": 1150, "era": "宋", "eraIdx": 4, "eraText": "南宋，约淳熙十三年（1186）退居石湖后作", "source": "范成大《四时田园杂兴六十首》之其三十一", "desc": "", "tags": ["田园杂兴", "农事生产", "童趣田园"], "note": "「耘田」直写男子日间下田除草的劳作场面，与夜间绩麻对举，勾勒小农家庭耕织并重的日常结构；末句儿童桑阴学种瓜，将「田」的劳动意象延伸至下一代，成为田园诗中劳动代际传承的经典画面。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4166.3, "y": 1592.9, "rot": 1.08, "w": 162}, {"id": "lit-35", "archive": "lit", "title": "范成大《四时田园杂兴六十首》", "author": "范成大", "quote": "梅子金黄杏子肥，麦花雪白菜花稀。日长篱落无人过，惟有蜻蜓蛱蝶飞。", "year": 1186, "era": "宋", "eraIdx": 4, "eraText": "南宋，约1186年", "source": "范成大《四时田园杂兴六十首》之其二十五", "desc": "", "tags": ["田园杂兴", "田园风光", "农时物候"], "note": "「麦花雪白菜花稀」以麦田扬花、油菜结籽点出初夏农时物候，「篱落无人过」侧写农忙时节人人下田、村中阒寂，静景中含繁忙农事，是范成大田园诗「以静写忙」的代表。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4777.2, "y": 1593.1, "rot": -2.15, "w": 162}, {"id": "lit-36", "archive": "lit", "title": "范成大《四时田园杂兴六十首》", "author": "范成大", "quote": "采菱辛苦废犁锄，血指流丹鬼质枯。无力买田聊种水，近来湖面亦收租！", "year": 1186, "era": "宋", "eraIdx": 4, "eraText": "南宋，约1186年", "source": "范成大《四时田园杂兴六十首》之其三十五", "desc": "", "tags": ["田园杂兴", "民生疾苦", "赋税苛敛"], "note": "此处「田」以反面方式呈现——农民失地（无力买田）而被迫「种水」采菱，连湖面亦被收租，揭示南宋土地兼并与苛捐杂税下「无田可耕」的悲惨处境，体现田园诗由闲适向讽谕民生深化的文学史转向。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4119.3, "y": 1706.5, "rot": 0.57, "w": 162}, {"id": "lit-37", "archive": "lit", "title": "杨万里《插秧歌》", "author": "杨万里", "quote": "田夫抛秧田妇接，小儿拔秧大儿插。笠是兜鍪蓑是甲，雨从头上湿到胛。", "year": 1127, "era": "宋", "eraIdx": 4, "eraText": "南宋（杨万里，1127—1206）", "source": "杨万里《插秧歌》", "desc": "", "tags": ["农事生产", "田家劳作", "诚斋体"], "note": "「田夫」「田妇」以身份命名人物，将全家总动员的稻田抢插场景写得如战场般紧张（笠为兜鍪、蓑为甲），「抛、接、拔、插」四动词使「田」成为动态劳动的舞台，尽显诚斋体新鲜活泼的写生特色。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4559.4, "y": 1366.9, "rot": 0.77, "w": 132}, {"id": "lit-38", "archive": "lit", "title": "陆游《时雨》", "author": "陆游", "quote": "时雨及芒种，四野皆插秧。家家麦饭美，处处菱歌长。", "year": 1125, "era": "宋", "eraIdx": 4, "eraText": "南宋（陆游，1125—1210）", "source": "陆游《时雨》", "desc": "", "tags": ["田野风光", "农时节气", "乡村风情"], "note": "「四野皆插秧」以开阔视野写芒种时节遍野水田的劳动图景，「麦饭」「菱歌」将田野物产与乡俗歌声交织，陆游以「惰农」自嘲反衬田家之乐，体现其晚年田园诗对乡村生活的深情认同。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4380.5, "y": 1416.6, "rot": -2.39, "w": 162}, {"id": "lit-39", "archive": "lit", "title": "翁卷《乡村四月》", "author": "翁卷", "quote": "绿遍山原白满川，子规声里雨如烟。乡村四月闲人少，才了蚕桑又插田。", "year": 1150, "era": "宋", "eraIdx": 4, "eraText": "南宋中后期", "source": "翁卷《乡村四月》（永嘉四灵之一）", "desc": "", "tags": ["农事生产", "田园风光", "江南乡村"], "note": "「白满川」暗指灌水的稻田映着天光，「才了蚕桑又插田」以「才」「又」两个虚字写尽农事衔接的紧凑，「插田」与「绿遍山原」前后呼应，交织成江南初夏声色鲜明的田园画卷。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4776.9, "y": 1442.2, "rot": -2.05, "w": 152}, {"id": "lit-40", "archive": "lit", "title": "辛弃疾《清平乐·村居》", "author": "辛弃疾", "quote": "茅檐低小，溪上青青草。醉里吴音相媚好，白发谁家翁媪？大儿锄豆溪东，中儿正织鸡笼。最喜小儿亡赖，溪头卧剥莲蓬。", "year": 1181, "era": "宋", "eraIdx": 4, "eraText": "南宋，约淳熙年间退居上饶带湖时期（1181年后）", "source": "辛弃疾《清平乐·村居》", "desc": "", "tags": ["乡村风情", "田家生活", "童趣田园"], "note": "「锄豆溪东」点出溪东豆田的田间劳作，词以白描勾勒农家三代人的分工——田中锄豆、家中织笼、溪头剥莲，将「田」融入完整温馨的农家生活图景，是宋词中田园题材开拓的标志之作。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4535.8, "y": 1592.6, "rot": 0.48, "w": 152}, {"id": "lit-41", "archive": "lit", "title": "辛弃疾《西江月·夜行黄沙道中》", "author": "辛弃疾", "quote": "明月别枝惊鹊，清风半夜鸣蝉。稻花香里说丰年，听取蛙声一片。", "year": 1150, "era": "宋", "eraIdx": 4, "eraText": "南宋，约淳熙八年（1181）后上饶闲居期间", "source": "辛弃疾《西江月·夜行黄沙道中》", "desc": "", "tags": ["夜行田野", "丰收喜悦", "田园风光"], "note": "「稻花香」以嗅觉写稻田，再由稻花联想丰年、以蛙声「说」丰年，将田野意象与农人丰收的期盼融为一体，是豪放词人笔下的恬美田园夜境，拓宽了词体的田园表现空间。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4306.1, "y": 1562.2, "rot": 0.78, "w": 162}, {"id": "lit-42", "archive": "lit", "title": "苏轼《浣溪沙》", "author": "苏轼", "quote": "簌簌衣巾落枣花，村南村北响缫车，牛衣古柳卖黄瓜。酒困路长惟欲睡，日高人渴漫思茶。敲门试问野人家。", "year": 1000, "era": "宋", "eraIdx": 4, "eraText": "北宋，元丰元年（1078）苏轼任徐州太守时", "source": "苏轼《浣溪沙》（徐门石潭谢雨道上作五首·其四）", "desc": "", "tags": ["乡村风情", "农事生产", "太守亲民"], "note": "久旱得雨后村南村北缫车齐响、枣花飘落、农人叫卖黄瓜，词人从听觉角度捕捉雨后乡村复苏的生机，「敲门试问野人家」更以地方官身份融入田家日常，为北宋词的农村题材开辟了新天地。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4102.2, "y": 1437.2, "rot": 1.82, "w": 132}, {"id": "lit-43", "archive": "lit", "title": "张可久《【黄钟】人月圆·山中书事》", "author": "张可久", "quote": "兴亡千古繁华梦，诗眼倦天涯。孔林乔木，吴宫蔓草，楚庙寒鸦。数间茅舍，藏书万卷，投老村家。山中何事？松花酿酒，春水煎茶。", "year": 1270, "era": "宋", "eraIdx": 4, "eraText": "元代（张可久，约1270—1348以后）", "source": "张可久《【黄钟】人月圆·山中书事》", "desc": "", "tags": ["闲适田园", "归隐山居", "元人散曲"], "note": "「投老村家」「松花酿酒，春水煎茶」将陶渊明的田园归隐传统转化为元代文人勘破兴亡后的山林闲适生活，「村家」「山中」意象承续宋元田园脉络，代表元散曲清丽一格中的田园书写。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 4325.4, "y": 1709.4, "rot": -0.91, "w": 162}, {"id": "lit-44", "archive": "lit", "title": "高启《春暮西园》", "author": "高启", "quote": "绿池芳草满晴波，春色都从雨里过。知是人家花落尽，菜畦今日蝶来多。", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "明代（明初）", "source": "高启《春暮西园》", "desc": "", "tags": ["田园怀旧", "田园即景", "暮春生机"], "note": "以「菜畦」这一田园意象收束全诗，花落而蝶来，暮春田园不显衰飒反见生趣，体现明初田园诗清新自然、虚实相生的审美趣味。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 5115.5, "y": 1439.8, "rot": -0.83, "w": 152}, {"id": "lit-45", "archive": "lit", "title": "查慎行《自湘东驿遵陆至芦溪》", "author": "查慎行", "quote": "丝缫细雨沾衣润，刀剪良苗出水齐。……春深无处不耕犁。", "year": 1696, "era": "元明清", "eraIdx": 5, "eraText": "清代，康熙五十七年（1718）四月", "source": "查慎行《自湘东驿遵陆至芦溪》，《敬业堂诗集·粤游集》", "desc": "", "tags": ["农事生产", "田园即景", "白描"], "note": "出水秧苗「刀剪」般齐整、深春处处耕犁，以白描活化江南春耕图景，是清代宋诗派田园—农事书写的典范，赵翼推许其为「香山、放翁后一人」。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 5546.7, "y": 1411.7, "rot": -1.61, "w": 142}, {"id": "lit-46", "archive": "lit", "title": "曹雪芹《红楼梦》", "author": "曹雪芹", "quote": "一畦春韭绿，十里稻花香。", "year": 1750, "era": "元明清", "eraIdx": 5, "eraText": "清代（约18世纪中叶）", "source": "曹雪芹《红楼梦》第十八回，林黛玉代贾宝玉拟《杏帘在望》", "desc": "", "tags": ["田园怀旧", "稻田意象", "颂圣田园"], "note": "大观园中的「稻香村」是贵族园林对田园的想象性移植，「春韭」「稻花」一联一气而下、色香兼备，成为中国文学中最著名的稻田意象之一，暗含对世外桃源式农庄生活的向往。元妃读后遂将「浣葛山庄」改名「稻香村」。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 5176.4, "y": 1558.9, "rot": 1.34, "w": 162}, {"id": "lit-47", "archive": "lit", "title": "何其芳《秋天》", "author": "何其芳", "quote": "放下饱食过稻香的镰刀，用背篓来装竹篱间肥硕的瓜果。秋天栖息在农家里。", "year": 1932, "era": "近现代", "eraIdx": 6, "eraText": "1932年", "source": "何其芳《秋天》，收入诗集《预言》", "desc": "", "tags": ["田园怀旧", "丰收喜悦", "稻田意象"], "note": "「饱食过稻香的镰刀」以拟人写尽丰收后的怡然，将古典田园诗的闲雅意境移植入现代新诗，是现代诗史上「田园牧歌」书写的经典样本。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 6167.5, "y": 1409.1, "rot": 1.52, "w": 132}, {"id": "lit-48", "archive": "lit", "title": "臧克家《三代》", "author": "臧克家", "quote": "孩子／在土里洗澡；", "year": 1942, "era": "近现代", "eraIdx": 6, "eraText": "1942年", "source": "臧克家《三代》，收入诗集《泥土的歌》", "desc": "", "tags": ["土地情结", "乡土中国", "农民命运"], "note": "全诗仅二十一字，以「土」贯穿三代人的生、劳、死，浓缩旧中国农民与土地生死相依的悲剧性命运，是「土地情结」最凝练的现代诗表达，与《老马》前后呼应。", "text": "爸爸／在土里流汗；\n爷爷／在土里葬埋。", "img": null, "hall": "C7", "hub": false, "x": 6125.3, "y": 1550.4, "rot": -1.33, "w": 152}, {"id": "lit-49", "archive": "lit", "title": "海子《麦地》", "author": "海子", "quote": "月亮下／连夜种麦的父亲／身上像流动金子。", "year": 1985, "era": "当代", "eraIdx": 7, "eraText": "1985年／1987年", "source": "海子《麦地》（1985），收入《海子诗全集》；另参《五月的麦地》（1987）「全世界的兄弟们／要在麦地里拥抱」", "desc": "", "tags": ["麦田意象", "土地情结", "生命哲思"], "note": "海子以15年乡村经验创造出「麦地」这一核心意象，将古典田园传统转化为承载苦难、感恩与人类性乌托邦想象的现代象征体系，他本人因此被称为「麦地诗人」，是古典田园意象现代转化的标志性案例。", "text": "……\n健康的麦地／健康的麦子／养我性命的麦子！", "img": null, "hall": "C7", "hub": true, "x": 7146.8, "y": 1413.1, "rot": -0.39, "w": 152}, {"id": "lit-50", "archive": "lit", "title": "莫言《红高粱家族》", "author": "莫言", "quote": "八月深秋，无边无际的高粱红成汪洋的血海。高粱高密辉煌，高粱凄婉可人，高粱爱情激荡。", "year": 1986, "era": "当代", "eraIdx": 7, "eraText": "1986年", "source": "莫言《红高粱家族》第一章", "desc": "", "tags": ["乡土中国", "生命哲思", "高粱地意象"], "note": "高粱地（田野）既是乡民赖以生存的家园，也是血性与抗争的「青纱帐」，田野被赋予原始生命力与历史悲壮感，构成莫言「高密东北乡」文学王国的奠基性意象。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 7522.2, "y": 1405.4, "rot": -1.01, "w": 142}, {"id": "lit-51", "archive": "lit", "title": "刘亮程《对一朵花微笑》", "author": "刘亮程", "quote": "一个听烦市嚣的人，躺在田野上听听虫鸣该是多么幸福。大地的音乐会永无休止。", "year": 1998, "era": "当代", "eraIdx": 7, "eraText": "20世纪90年代（散文集1998年初版）", "source": "刘亮程《对一朵花微笑》，收入散文集《一个人的村庄》", "desc": "", "tags": ["田园怀旧", "乡土中国", "生命哲思"], "note": "以「一个人」的视角谛听田野虫鸣，将荒野田园升华为抗衡市嚣的精神栖息地，代表当代乡土散文「万物有灵」式的田园书写，为消逝中的农耕乡村留下挽歌。", "text": "", "img": null, "hall": "C7", "hub": false, "x": 7104.5, "y": 1529.3, "rot": -1.98, "w": 142}, {"id": "art-1", "archive": "art", "title": "《收割者》（The Harvesters）", "author": "老彼得·勃鲁盖尔", "quote": "", "year": 1565, "era": "元明清", "eraIdx": 5, "eraText": "1565年", "source": "纽约大都会艺术博物馆", "desc": "金黄麦田中农夫弯腰收割，有人于树下进餐，远处城堡与海港，人物繁密而渺小", "tags": ["尼德兰", "文艺复兴", "收割"], "note": "勃鲁盖尔\"月令\"系列之一，以劳作史诗取代宗教叙事", "text": "", "img": "art_1.jpg", "hall": "C5", "hub": false, "x": 5485.5, "y": 1925.5, "rot": -1.08, "w": 142}, {"id": "art-2", "archive": "art", "title": "《拾穗者》（The Gleaners）", "author": "让-弗朗索瓦·米勒", "quote": "", "year": 1857, "era": "元明清", "eraIdx": 5, "eraText": "1857年", "source": "巴黎奥赛博物馆", "desc": "三位农妇弯腰拾取收割后的麦穗，身后麦垛高耸、监工骑马，地平线横贯画面", "tags": ["巴比松", "现实主义", "拾穗"], "note": "首展时被批为\"煽动\"，今已成为法国农民形象的世界级象征", "text": "", "img": "art_2.jpg", "hall": "C8", "hub": false, "x": 5599.3, "y": 2081.8, "rot": 1.38, "w": 142}, {"id": "art-3", "archive": "art", "title": "《晚祷》（The Angelus）", "author": "让-弗朗索瓦·米勒", "quote": "", "year": 1859, "era": "元明清", "eraIdx": 5, "eraText": "1857—1859年", "source": "巴黎奥赛博物馆", "desc": "暮色田野中一对农夫夫妇闻远处钟声摘帽低头祈祷，推车静置，气氛凝重", "tags": ["巴比松", "现实主义", "宗教情感"], "note": "原名《为收成祈祷》；达利曾坚称画中埋藏图像秘密，引发学界长期讨论", "text": "", "img": "art_3.jpg", "hall": "C8", "hub": false, "x": 5703.1, "y": 2108.0, "rot": 2.12, "w": 152}, {"id": "art-4", "archive": "art", "title": "《干草车》（The Hay Wain）", "author": "约翰·康斯太勃尔", "quote": "", "year": 1821, "era": "元明清", "eraIdx": 5, "eraText": "1821年", "source": "英国国家美术馆（伦敦）", "desc": "萨福克乡村——干草车涉水过河，磨坊农舍点缀，雷雨初歇的天光铺满画面", "tags": ["风景画", "浪漫主义", "英国"], "note": "1824年巴黎沙龙金奖，\"画我所见\"的自然主义风景宣言", "text": "", "img": "art_4.jpg", "hall": "C8", "hub": false, "x": 5368.2, "y": 2151.1, "rot": 2.34, "w": 132}, {"id": "art-5", "archive": "art", "title": "《干草收获》（Haymaking）", "author": "卡米耶·毕沙罗", "quote": "", "year": 1887, "era": "元明清", "eraIdx": 5, "eraText": "1887年前后", "source": "各美术馆（同题材多版本）", "desc": "埃拉尼村外——村妇农夫摊晒、翻动干草，树影婆娑，笔意渐近点彩", "tags": ["印象派", "新印象", "农事"], "note": "毕沙罗一生反复书写农民与田地——\"农民的画家\"之名不虚", "text": "", "img": "art_5.jpg", "hall": "C8", "hub": false, "x": 5295.1, "y": 2246.5, "rot": -2.18, "w": 142}, {"id": "art-6", "archive": "art", "title": "《麦田与柏树》（Wheatfield with Cypresses）", "author": "文森特·梵高", "quote": "", "year": 1889, "era": "元明清", "eraIdx": 5, "eraText": "1889年", "source": "英国国家美术馆（伦敦）", "desc": "金色麦浪翻滚如火焰，深色柏树冲天而起，白云涡卷，笔触旋转", "tags": ["后印象派", "圣雷米", "风景"], "note": "梵高自称最好的夏景之一，同题另绘两幅习作", "text": "", "img": "art_6.jpg", "hall": "C8", "hub": false, "x": 5562.7, "y": 2267.0, "rot": -2.43, "w": 152}, {"id": "art-7", "archive": "art", "title": "《麦田群鸦》（Wheatfield with Crows）", "author": "文森特·梵高", "quote": "", "year": 1890, "era": "元明清", "eraIdx": 5, "eraText": "1890年", "source": "阿姆斯特丹梵高博物馆", "desc": "黑鸦低飞于三条岔路的麦田上空，乌云压境，黄与黑剧烈对撞，无路通向远方", "tags": ["后印象派", "奥维尔", "绝笔"], "note": "常被视为遗书，但学者考证作于自杀前三周左右，而非当日", "text": "", "img": "art_7.jpg", "hall": "C8", "hub": false, "x": 5694.8, "y": 2290.3, "rot": -0.24, "w": 142}, {"id": "art-8", "archive": "art", "title": "《播种者》（仿米勒）", "author": "文森特·梵高", "quote": "", "year": 1888, "era": "元明清", "eraIdx": 5, "eraText": "1888年", "source": "各馆收藏（多版本）", "desc": "阿尔勒田野——明黄太阳悬于钴蓝天幕，播种者呈紫蓝色剪影，大步扬种", "tags": ["后印象派", "阿尔勒", "摹古"], "note": "梵高对米勒的\"色彩翻译\"——用纯色块重写现实主义经典", "text": "", "img": "art_8.jpg", "hall": "C8", "hub": true, "x": 5370.9, "y": 2227.5, "rot": -2.59, "w": 162}, {"id": "art-9", "archive": "art", "title": "《白嘴鸦飞来了》（The Rooks Have Returned）", "author": "阿列克谢·萨符拉索夫", "quote": "", "year": 1871, "era": "元明清", "eraIdx": 5, "eraText": "1871年", "source": "莫斯科特列季亚科夫画廊", "desc": "残雪初融的村路、木屋与白嘴鸦阵，光秃树梢凝着春寒——春天的第一声", "tags": ["巡回展览派", "春景", "乡愁"], "note": "俄罗斯民族风景画的开山之作，以乡愁呼唤苏醒的土地", "text": "", "img": "art_9.jpg", "hall": "C8", "hub": false, "x": 5843.2, "y": 2169.0, "rot": -1.01, "w": 132}, {"id": "art-10", "archive": "art", "title": "《美国哥特式》（American Gothic）", "author": "格兰特·伍德", "quote": "", "year": 1930, "era": "近现代", "eraIdx": 6, "eraText": "1930年", "source": "芝加哥艺术学院", "desc": "卡彭特哥特式木板房前——农夫手持草叉、长脸女儿并肩而立，尖顶窗映出田野", "tags": ["地方主义", "美国", "肖像"], "note": "形象被无数次戏仿，已沉入美国视觉文化基因", "text": "", "img": "art_10.jpg", "hall": "C8", "hub": false, "x": 6189.2, "y": 1927.1, "rot": -1.74, "w": 152}, {"id": "art-11", "archive": "art", "title": "《我与村庄》（I and the Village）", "author": "马克·夏加尔", "quote": "", "year": 1911, "era": "元明清", "eraIdx": 5, "eraText": "1911年", "source": "纽约现代艺术博物馆（MoMA）", "desc": "农夫与山羊对视，村落、教堂、犁田与绿面人交错悬浮，几何分割的乡愁", "tags": ["立体主义", "乡愁", "梦幻"], "note": "巴黎时期对维捷布斯克田园记忆的立体主义重组", "text": "", "img": "art_11.jpg", "hall": "C8", "hub": false, "x": 5141.0, "y": 2424.5, "rot": 0.77, "w": 152}, {"id": "art-12", "archive": "art", "title": "《收割者的报酬》（La Paye des moissonneurs）", "author": "莱昂·莱尔米特", "quote": "", "year": 1882, "era": "元明清", "eraIdx": 5, "eraText": "1882年", "source": "各馆收藏（另有色粉版本）", "desc": "收割结算场景——工头点算钱币，农工排队领薪，身后麦垛与暮色", "tags": ["自然主义", "法国", "劳工"], "note": "以素描精度书写农村现实，梵高曾在致提奥的信中盛赞其人其画", "text": "", "img": "art_12.jpg", "hall": "C5", "hub": false, "x": 5163.2, "y": 2294.0, "rot": 2.33, "w": 142}, {"id": "art-13", "archive": "art", "title": "《圣维克多山》系列", "author": "保罗·塞尚", "quote": "", "year": 1904, "era": "元明清", "eraIdx": 5, "eraText": "1902—1904年（晚年系列）", "source": "费城艺术博物馆等（系列分藏）", "desc": "圣维克多山下的田野与村庄被几何化为色块，一条大路弧线引目上山", "tags": ["后印象派", "普罗旺斯", "构成"], "note": "\"用圆柱、球体、圆锥处理自然\"宣言的实践，田野由此走向立体主义", "text": "", "img": "art_13.jpg", "hall": "C8", "hub": false, "x": 5850.9, "y": 2298.8, "rot": 0.65, "w": 142}, {"id": "art-14", "archive": "art", "title": "《威文侯公园》（Wivenhoe Park）", "author": "约翰·康斯太勃尔", "quote": "", "year": 1816, "era": "元明清", "eraIdx": 5, "eraText": "1816年", "source": "华盛顿国家美术馆", "desc": "艾塞克斯庄园——湖面天鹅、乳牛与鹿群散布，牧场景致在开阔云天下舒展", "tags": ["风景画", "浪漫主义", "英国"], "note": "为订婚贺礼而作，英式田园牧歌的标本", "text": "", "img": "art_14.jpg", "hall": "C8", "hub": false, "x": 5318.7, "y": 2110.1, "rot": -2.21, "w": 132}, {"id": "art-15", "archive": "art", "title": "《克里斯蒂娜的世界》（Christina's World）", "author": "安德鲁·怀斯", "quote": "", "year": 1948, "era": "近现代", "eraIdx": 6, "eraText": "1948年", "source": "纽约现代艺术博物馆（MoMA）", "desc": "女孩卧于枯黄草地，向远处孤屋缓缓爬去，缅因乡野寂寥无垠，蛋彩坦培拉", "tags": ["美国", "写实", "蛋彩"], "note": "以蛋彩绘就的美国式孤独的代名词，灵感来自患小儿麻痹的邻居", "text": "", "img": "art_15.jpg", "hall": "C8", "hub": false, "x": 6296.0, "y": 2166.2, "rot": 1.75, "w": 132}, {"id": "art-16", "archive": "art", "title": "《农民的婚礼》（The Peasant Wedding）", "author": "老彼得·勃鲁盖尔", "quote": "", "year": 1568, "era": "元明清", "eraIdx": 5, "eraText": "1568年", "source": "维也纳艺术史博物馆", "desc": "谷仓婚礼宴席——长桌铺陈、抬汤而过、宾客满座，背景粮囤与农具", "tags": ["尼德兰", "文艺复兴", "民俗"], "note": "以粮食与田地为底色的农民群像，人间烟火即史诗", "text": "", "img": "art_16.jpg", "hall": "C8", "hub": false, "x": 5686.5, "y": 1995.3, "rot": -2.07, "w": 132}, {"id": "art-17", "archive": "art", "title": "榆林窟第25窟《耕获图》", "author": "敦煌画工（佚名）", "quote": "", "year": 800, "era": "隋唐", "eraIdx": 3, "eraText": "中唐（约8世纪）", "source": "甘肃瓜州榆林窟第25窟（敦煌艺术群）", "desc": "弥勒经变下部——一农夫扶犁、黑牛挽辕翻耕，旁有撒种、收割场景，田垄纵横，设色醇厚", "tags": ["壁画", "敦煌", "耕作", "佛教"], "note": "敦煌壁画中最完整的唐代农耕图像之一，是曲辕犁使用的形象实证", "text": "", "img": "art_17.jpg", "hall": "C5", "hub": false, "x": 3206.3, "y": 1967.0, "rot": -0.48, "w": 152}, {"id": "art-18", "archive": "art", "title": "东汉《牛耕图》画像石", "author": "佚名", "quote": "", "year": -100, "era": "秦汉", "eraIdx": 1, "eraText": "东汉（约2世纪）", "source": "陕西米脂等地汉墓出土（陕北画像石馆等藏）", "desc": "横式构图——一牛一犁，农夫扶犁扬鞭，后有播种者，田界以斜线分割，剪影式刀法", "tags": ["画像石", "汉代", "牛耕"], "note": "汉代\"二牛抬杠\"耕法的典型图像，中国早期牛耕的实证材料", "text": "", "img": "art_18.jpg", "hall": "C5", "hub": false, "x": 1170.4, "y": 2005.8, "rot": -0.89, "w": 162}, {"id": "art-19", "archive": "art", "title": "嘉峪关《耕耙图》墓砖画", "author": "佚名", "quote": "", "year": 320, "era": "魏晋南北朝", "eraIdx": 2, "eraText": "魏晋（3—4世纪）", "source": "甘肃嘉峪关新城魏晋墓群砖画", "desc": "一农夫戴巾牵畜拉耙碎土，另一人随后点种，线条稚拙生动，土黄施彩", "tags": ["砖画", "河西走廊", "耙地"], "note": "墓室生活壁画反映屯田制度下的河西农业，被誉为\"地下画廊\"", "text": "", "img": "art_19.jpg", "hall": "C5", "hub": false, "x": 2124.6, "y": 2014.5, "rot": 1.63, "w": 132}, {"id": "art-20", "archive": "art", "title": "张择端《清明上河图》（郊野段）", "author": "张择端", "quote": "", "year": 1000, "era": "宋", "eraIdx": 4, "eraText": "北宋（12世纪初）", "source": "故宫博物院（北京）", "desc": "长卷开篇——汴京郊野农舍、田畴阡陌、归樵负薪者渐入市集，由静入喧", "tags": ["风俗画", "长卷", "北宋"], "note": "以城市叙事开卷于田野——\"田\"是这幅盛世长卷的序章", "text": "", "img": "art_20.jpg", "hall": "C8", "hub": false, "x": 4144.6, "y": 1951.5, "rot": -0.92, "w": 162}, {"id": "art-21", "archive": "art", "title": "楼璹《耕织图》", "author": "楼璹", "quote": "", "year": 1150, "era": "宋", "eraIdx": 4, "eraText": "南宋绍兴年间（12世纪）", "source": "原作已佚，元明摹本及清代刻本传世", "desc": "耕图21幅——浸种、耕、耙、耨、插秧、收割、入仓等全过程白描，配五言诗", "tags": ["农事图谱", "宫廷", "白描"], "note": "中国影响最深远的农事图谱，被历代帝王钦命摹刻颁行", "text": "", "img": "art_21.jpg", "hall": "C5", "hub": true, "x": 4583.8, "y": 2002.5, "rot": -2.59, "w": 162}, {"id": "art-22", "archive": "art", "title": "马远《踏歌图》", "author": "马远", "quote": "", "year": 1150, "era": "宋", "eraIdx": 4, "eraText": "南宋", "source": "故宫博物院（北京）", "desc": "一角山水间田垄蜿蜒，几位农人踏歌而行，近石巨嶂、远峰朦胧", "tags": ["山水", "人物", "马一角"], "note": "取\"丰年人乐业，垄上踏歌行\"诗意，宫廷画家笔下的农家乐", "text": "", "img": "art_22.jpg", "hall": "C8", "hub": false, "x": 4139.6, "y": 2088.8, "rot": -0.72, "w": 162}, {"id": "art-23", "archive": "art", "title": "赵孟頫《鹊华秋色图》", "author": "赵孟頫", "quote": "", "year": 1295, "era": "元明清", "eraIdx": 5, "eraText": "元元贞元年（1295年）", "source": "台北故宫博物院", "desc": "济南郊外——华不注山与鹊山遥相望，洲渚间红树芦荻、渔舟农夫，青绿复古", "tags": ["文人画", "复古", "平远"], "note": "以书法性用笔描绘北方田野，元代文人画复古运动的里程碑", "text": "", "img": "art_23.jpg", "hall": "C8", "hub": false, "x": 5113.0, "y": 1993.9, "rot": -1.16, "w": 152}, {"id": "art-24", "archive": "art", "title": "沈周《东庄图》册", "author": "沈周", "quote": "", "year": 1500, "era": "元明清", "eraIdx": 5, "eraText": "明代（15世纪末）", "source": "南京博物院", "desc": "为友人吴宽庄园写真二十一景——稻畦、麦垅、桑园、鹤洞，水墨淡设色", "tags": ["吴门", "庄园", "写生"], "note": "明代庄园经济与田园林居生活的视觉档案，吴门画派奠基作", "text": "", "img": "art_24.jpg", "hall": "C8", "hub": false, "x": 5371.5, "y": 1921.4, "rot": 0.18, "w": 152}, {"id": "art-25", "archive": "art", "title": "焦秉贞《御制耕织图》", "author": "焦秉贞（绘）", "quote": "", "year": 1696, "era": "元明清", "eraIdx": 5, "eraText": "清康熙三十五年（1696年）", "source": "清内府刻本，海内外各馆多有收藏", "desc": "耕、织各23幅——殿阁田舍井然，人物工笔法，构图参用西洋焦点透视", "tags": ["木刻版画", "宫廷", "中西合璧"], "note": "康熙帝作序颁行天下，清代农业政策的图像宣传，也是中西绘画技法交汇的实例", "text": "", "img": "art_25.jpg", "hall": "C5", "hub": true, "x": 5205.9, "y": 2095.2, "rot": 1.88, "w": 132}, {"id": "art-26", "archive": "art", "title": "王祯《农书》插图", "author": "刻工佚名", "quote": "", "year": 1313, "era": "元明清", "eraIdx": 5, "eraText": "元皇庆二年（1313年）", "source": "《王祯农书》历代刊本", "desc": "农耕、农器、灌溉机械木刻插图三百余幅——犁、耧、水排皆具图解", "tags": ["农书插图", "木刻", "元代"], "note": "中国农学图像传统的集大成之作，\"农器图谱\"体例影响后世农书", "text": "", "img": "art_26.jpg", "hall": "C5", "hub": false, "x": 5337.7, "y": 2003.3, "rot": -1.06, "w": 152}, {"id": "art-27", "archive": "art", "title": "《天工开物》\"乃粒\"插图", "author": "刻工佚名", "quote": "", "year": 1637, "era": "元明清", "eraIdx": 5, "eraText": "明崇祯十年（1637年）", "source": "宋应星《天工开物》初刻本", "desc": "耕田、灌溉、收割、水利机械版画，构图严谨，具科学图解性质", "tags": ["科技版画", "明代", "农器"], "note": "早期\"技术图谱\"的审美典范，被誉为17世纪的工艺视觉志", "text": "", "img": "art_27.jpg", "hall": "C5", "hub": false, "x": 5808.9, "y": 1966.9, "rot": -0.31, "w": 142}, {"id": "art-28", "archive": "art", "title": "李可染《牧牛图》系列", "author": "李可染", "quote": "", "year": 2060, "era": "当代", "eraIdx": 7, "eraText": "20世纪40—80年代", "source": "各美术馆及私人收藏", "desc": "暮归牧童骑牛穿柳渡田，水墨淋漓，常钤\"孺子牛\"印", "tags": ["水墨", "现代", "牧歌"], "note": "画室名\"师牛堂\"——牛是力耕与忠厚的象征，也是其变法母题之一", "text": "", "img": "art_28.jpg", "hall": "C8", "hub": false, "x": 7662.4, "y": 2318.1, "rot": -1.36, "w": 162}, {"id": "art-29", "archive": "art", "title": "徐悲鸿《九州无事乐耕耘》", "author": "徐悲鸿", "quote": "", "year": 1951, "era": "近现代", "eraIdx": 6, "eraText": "1951年", "source": "徐悲鸿纪念馆（北京）", "desc": "三位农夫、一牛一驴耕耙并行于田，远处古柏新绿，横幅巨制，写实中融传统笔墨", "tags": ["写实主义", "现代", "主题创作"], "note": "以农耕劳作喻和平建设，徐悲鸿晚年人物画代表作", "text": "", "img": "art_29.jpg", "hall": "C8", "hub": false, "x": 6599.9, "y": 2137.2, "rot": -1.2, "w": 132}, {"id": "art-30", "archive": "art", "title": "古元《铡草》", "author": "古元", "quote": "", "year": 1940, "era": "近现代", "eraIdx": 6, "eraText": "1940年", "source": "中国美术馆等", "desc": "延安木刻——农民俯身铡草，黑白对比强烈，刀法粗犷有力，充满劳动节奏", "tags": ["木刻", "延安", "版画"], "note": "解放区版画的劳动美学代表，曾在重庆木刻展获奖，影响一代版画家", "text": "", "img": "art_30.jpg", "hall": "C8", "hub": false, "x": 6196.7, "y": 2143.5, "rot": 0.54, "w": 132}, {"id": "art-31", "archive": "art", "title": "罗中立《父亲》", "author": "罗中立", "quote": "", "year": 1980, "era": "当代", "eraIdx": 7, "eraText": "1980年", "source": "中国美术馆（北京）", "desc": "巨幅头像——满脸沟壑的老农手捧粗瓷碗，背景铺展金黄田原，照相写实尺幅", "tags": ["油画", "伤痕美术", "现实主义"], "note": "第二届全国青年美展金奖，以领袖像的规格描绘普通农民，中国当代美术史地标", "text": "", "img": "art_31.jpg", "hall": "C8", "hub": false, "x": 7357.3, "y": 1963.8, "rot": 1.03, "w": 132}, {"id": "art-32", "archive": "art", "title": "王式廓《血衣》", "author": "王式廓", "quote": "", "year": 1959, "era": "近现代", "eraIdx": 6, "eraText": "1959年素描稿（油画未完成）", "source": "素描藏中国美术馆等", "desc": "土地改革斗争会——老妇举起血衣控诉，愤怒的农民群像层层环绕，黑白素描", "tags": ["素描", "革命历史", "未完成"], "note": "被誉为中国素描史的巅峰；油画终未完成，成为画史著名遗憾", "text": "", "img": "art_32.jpg", "hall": "C8", "hub": false, "x": 6766.6, "y": 2087.5, "rot": 0.1, "w": 162}, {"id": "art-33", "archive": "art", "title": "吴冠中《水田》系列", "author": "吴冠中", "quote": "", "year": 2085, "era": "当代", "eraIdx": 7, "eraText": "20世纪80—90年代", "source": "各馆及私人收藏", "desc": "江南水田被抽象为黑白色块与天空倒影，点线面构成一首无声的田园曲", "tags": ["抽象", "现代", "江南"], "note": "\"形式美\"探索的代表——田在此成为纯粹的形式母题", "text": "", "img": "art_33.jpg", "hall": "C8", "hub": false, "x": 7742.0, "y": 2297.6, "rot": -2.37, "w": 162}, {"id": "art-34", "archive": "art", "title": "《大地》（The Good Earth）", "author": "西德尼·富兰克林导演", "quote": "", "year": 1937, "era": "近现代", "eraIdx": 6, "eraText": "1937年", "source": "米高梅（MGM）出品，改编自赛珍珠同名小说", "desc": "中国北方农田上的农民王龙，灾荒、蝗灾与土地聚散；好莱坞摄影棚里搭出的\"中国田野\"", "tags": ["好莱坞", "中国题材", "土地史诗"], "note": "露易丝·赖纳凭此获奥斯卡影后；西方人眼中最经典的\"中国农民\"影像。", "text": "", "img": "art_34.jpg", "hall": "C8", "hub": false, "x": 6356.4, "y": 2002.4, "rot": 2.19, "w": 162}, {"id": "art-35", "archive": "art", "title": "《乱世佳人》（Gone with the Wind）", "author": "维克多·弗莱明导演", "quote": "", "year": 1939, "era": "近现代", "eraIdx": 6, "eraText": "1939年", "source": "米高梅出品，改编自玛格丽特·米切尔小说", "desc": "美国南方塔拉庄园的棉花田与红土，斯嘉丽\"土地是唯一永恒的东西\"的名言", "tags": ["美国南方", "庄园", "棉花田"], "note": "奥斯卡最佳影片，\"土地\"是好莱坞黄金年代的核心母题之一。", "text": "", "img": "art_35.jpg", "hall": "C8", "hub": false, "x": 6494.9, "y": 1988.9, "rot": 1.04, "w": 152}, {"id": "art-36", "archive": "art", "title": "《愤怒的葡萄》（The Grapes of Wrath）", "author": "约翰·福特导演", "quote": "", "year": 1940, "era": "近现代", "eraIdx": 6, "eraText": "1940年", "source": "二十世纪福克斯出品，改编自斯坦贝克小说", "desc": "俄克拉荷马尘暴过后，乔德一家变卖田产、西迁加州寻工；沙尘、破卡车与无尽公路", "tags": ["大萧条", "失地农民", "迁徙"], "note": "获奥斯卡最佳导演，美国\"失地农民\"题材的永恒经典。", "text": "", "img": "art_36.jpg", "hall": "C8", "hub": false, "x": 6735.1, "y": 1969.4, "rot": -2.18, "w": 132}, {"id": "art-38", "archive": "art", "title": "《木屐树》（L'albero degli zoccoli）", "author": "埃曼诺·奥尔米", "quote": "", "year": 1978, "era": "近现代", "eraIdx": 6, "eraText": "1978年", "source": "意大利出品", "desc": "19世纪末意大利伦巴第佃农四季：春耕、放牛、劳作与节庆，近乎纪录片的昏黄影调", "tags": ["佃农", "意大利乡村", "慢电影"], "note": "获戛纳金棕榈，被称\"电影史上的田园史诗\"。", "text": "", "img": "art_38.jpg", "hall": "C8", "hub": false, "x": 6199.9, "y": 2238.1, "rot": 0.44, "w": 162}, {"id": "art-39", "archive": "art", "title": "《苔丝》（Tess）", "author": "罗曼·波兰斯基导演", "quote": "", "year": 1979, "era": "当代", "eraIdx": 7, "eraText": "1979年", "source": "法国出品，改编自托马斯·哈代小说", "desc": "英国威塞克斯乡村，苔丝在金黄麦田与奶牛场间辗转命运；古典油画般的田园光影", "tags": ["英国乡村", "麦田", "命运悲剧"], "note": "获戛纳金棕榈，哈代\"威塞克斯田园\"最著名影像化。", "text": "", "img": "art_39.jpg", "hall": "C8", "hub": false, "x": 7165.0, "y": 1996.0, "rot": -1.54, "w": 142}, {"id": "art-40", "archive": "art", "title": "《种树的牧羊人》（L'homme qui plantait des arbres）", "author": "弗雷德里克·贝克动画短片", "quote": "", "year": 1987, "era": "当代", "eraIdx": 7, "eraText": "1987年", "source": "加拿大国家电影局（NFB）出品，改编自让·吉奥诺小说", "desc": "普罗旺斯荒原上，孤身牧羊人四十年如一日播种橡实，荒漠终成森林；手绘油画风格", "tags": ["动画短片", "植树", "荒漠变良田"], "note": "获奥斯卡最佳动画短片，土地修复主题的世界经典。", "text": "", "img": "art_40.jpg", "hall": "C8", "hub": false, "x": 7405.5, "y": 1983.0, "rot": 1.56, "w": 142}, {"id": "art-41", "archive": "art", "title": "《龙猫》（となりのトトロ）", "author": "宫崎骏，吉卜力", "quote": "", "year": 1988, "era": "当代", "eraIdx": 7, "eraText": "1988年", "source": "德间书店/吉卜力出品", "desc": "昭和初年日本乡间，小月与小梅搬入稻田环绕的老宅，龙猫在樟树与田埂间出没", "tags": ["吉卜力", "日本乡村", "稻田"], "note": "对日式田园乡愁的极致塑造，影响深远的动画经典。", "text": "", "img": "art_41.jpg", "hall": "C8", "hub": false, "x": 7595.3, "y": 1921.4, "rot": -0.48, "w": 142}, {"id": "art-42", "archive": "art", "title": "《与狼共舞》（Dances with Wolves）", "author": "凯文·科斯特纳导演并主演", "quote": "", "year": 1990, "era": "当代", "eraIdx": 7, "eraText": "1990年", "source": "奥利安影业出品", "desc": "美国中西部大草原，邓巴中尉与苏族人在野牛群与麦田般的大草原因相知", "tags": ["西部草原", "印第安", "自然史诗"], "note": "获奥斯卡最佳影片等七项大奖。", "text": "", "img": "art_42.jpg", "hall": "C8", "hub": false, "x": 7833.1, "y": 2011.3, "rot": -0.2, "w": 132}, {"id": "art-43", "archive": "art", "title": "《岁月的童话》（おもひでぽろぽろ）", "author": "高畑勋，吉卜力", "quote": "", "year": 1991, "era": "当代", "eraIdx": 7, "eraText": "1991年", "source": "吉卜力出品", "desc": "东京白领妙子到山形乡下帮农，插秧、种红花、晒柿饼，童年记忆与田园劳动交叠", "tags": ["吉卜力", "日本田园", "农耕日常"], "note": "高畑勋代表作，细致到农时节气的\"农业动画教科书\"。", "text": "", "img": "art_43.jpg", "hall": "C8", "hub": false, "x": 7167.7, "y": 2085.4, "rot": 2.25, "w": 152}, {"id": "art-44", "archive": "art", "title": "《天兆》（Signs）", "author": "奈特·沙马兰导演", "quote": "", "year": 2002, "era": "当代", "eraIdx": 7, "eraText": "2002年", "source": "试金石影业/ Blinding Edge", "desc": "宾州玉米田里一夜之间出现巨型 crop circles，牧师格雷厄姆一家在农舍与田地上直面\"入侵\"", "tags": ["玉米田", "悬疑", "科幻寓言"], "note": "农田怪圈意象流行文化的重要推手之一。", "text": "", "img": "art_44.jpg", "hall": "C8", "hub": false, "x": 7307.1, "y": 2097.3, "rot": 1.74, "w": 162}, {"id": "art-45", "archive": "art", "title": "《冷山》（Cold Mountain）", "author": "安东尼·明格拉导演", "quote": "", "year": 2003, "era": "当代", "eraIdx": 7, "eraText": "2003年", "source": "米拉麦克斯出品，改编自查尔斯·弗雷泽小说", "desc": "美国南北战争时期，英曼穿越战火回乡，艾达在山地农场学会耕种求生；蓝岭山脉的四季", "tags": ["山地农场", "战争与归乡"], "note": "获奥斯卡最佳女配角（齐薇格），\"土地即归处\"的内战史诗。", "text": "", "img": "art_45.jpg", "hall": "C8", "hub": false, "x": 7431.2, "y": 2125.1, "rot": -0.61, "w": 142}, {"id": "art-46", "archive": "art", "title": "《哪啊哪啊神去村》（WOOD JOB!）", "author": "矢口史靖导演", "quote": "", "year": 2014, "era": "当代", "eraIdx": 7, "eraText": "2014年", "source": "日本东映等出品，改编自三浦紫苑小说", "desc": "落榜高中生来到三重县深山\"神去村\"学林业，祭典、巨木与梯田梯级；笑泪交加的林业青春物语", "tags": ["日本山村", "林业", "青春成长"], "note": "让\"林业\"题材在商业片上获得罕见成功。", "text": "", "img": "art_46.jpg", "hall": "C8", "hub": false, "x": 7661.7, "y": 2097.6, "rot": 1.51, "w": 162}, {"id": "art-47", "archive": "art", "title": "《星际穿越》（Interstellar）", "author": "克里斯托弗·诺兰", "quote": "", "year": 2014, "era": "当代", "eraIdx": 7, "eraText": "2014年", "source": "派拉蒙/华纳兄弟/传奇影业出品", "desc": "末日尘暴中的美国玉米农场，库珀在麦田怪圈般的引力指引下离家奔赴星海", "tags": ["科幻", "玉米农场", "末日农业"], "note": "开篇玉米田实拍动员数百英亩农田，\"土地—星辰\"双重乡愁。", "text": "", "img": "art_47.jpg", "hall": "C8", "hub": false, "x": 7754.8, "y": 2148.8, "rot": -1.21, "w": 132}, {"id": "art-48", "archive": "art", "title": "《脸庞，村庄》（Visages, villages）", "author": "阿涅斯·瓦尔达与JR联合执导纪录片", "quote": "", "year": 2017, "era": "当代", "eraIdx": 7, "eraText": "2017年", "source": "法国出品", "desc": "法国乡村一路上，两人为矿工、农妇、邮差拍下巨幅肖像贴上墙与谷仓，村庄成为画廊", "tags": ["纪录片", "法国乡村", "公共艺术"], "note": "获奥斯卡最佳纪录片提名，\"村庄\"与\"记忆\"的影像礼赞。", "text": "", "img": "art_48.jpg", "hall": "C8", "hub": false, "x": 7349.8, "y": 2264.7, "rot": -0.08, "w": 152}, {"id": "art-49", "archive": "art", "title": "《蜂蜜之地》（Honeyland）", "author": "塔玛拉·科特夫斯卡、卢博米尔·斯特凡诺夫联合执导纪录片", "quote": "", "year": 2019, "era": "当代", "eraIdx": 7, "eraText": "2019年", "source": "北马其顿出品", "desc": "北马其顿偏远山村，养蜂人哈蒂兹与病母在荒野采蜜，游牧商贩一家的到来打破平衡", "tags": ["纪录片", "养蜂", "荒野与土地"], "note": "影史罕见同时入围奥斯卡最佳纪录长片与最佳国际影片的作品。", "text": "", "img": "art_49.jpg", "hall": "C8", "hub": false, "x": 7468.2, "y": 2274.3, "rot": -0.23, "w": 152}, {"id": "art-50", "archive": "art", "title": "《海蒂和爷爷》（Heidi）", "author": "阿兰·葛斯彭纳导演", "quote": "", "year": 2015, "era": "当代", "eraIdx": 7, "eraText": "2015年", "source": "德国/瑞士/南非联合出品，改编自约翰娜·施皮里小说", "desc": "阿尔卑斯山草甸，海蒂与爷爷、放羊娃皮特在山坡与花海间奔跑；雪山牧场景致如画", "tags": ["阿尔卑斯", "牧场", "儿童文学改编"], "note": "欧洲年度票房冠军之一，山乡童真的当代重塑。", "text": "", "img": "art_50.jpg", "hall": "C8", "hub": false, "x": 7123.9, "y": 2249.9, "rot": 0.45, "w": 162}];
